        | where (ProcessCommandLine contains "/tmp/.dbus" and ProcessCommandLine has_any ("curl", "chmod"))
            or (ProcessCommandLine contains "iwr -Uri" and ProcessCommandLine contains "win.exe" and ProcessCommandLine contains @"\svchost.exe")
        | project Timestamp, DeviceName, Signal="LazyOwn beacon quick-start one-liner", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath matches regex @"[/\\]sessions[/\\][^/\\]+$" and FileName in~ ("key.aes", "c2_launch.env", "c2_launch.sh", "rbac_initial_admin.txt", "users_initial_admin.txt", "sessionLazyOwn.json", "LazyOwn_session_report.csv"))
            or FolderPath contains "/sessions/captured_images/"
            or FileName =~ ".c2_credentials.txt"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, FileName)[0])
        | project Timestamp, DeviceName, Signal="LazyOwn session files", Detail=strcat(Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where (ActionType == "ListeningConnectionCreated" and InitiatingProcessCommandLine has_any ("lazyc2.py", "lazyown_mcp.py"))
            or RemoteUrl endswith "c2.lazyown.org"
        | project Timestamp, DeviceName, Signal="LazyOwn listener or DNS C2 zone", Detail=strcat(LocalIP, ":", LocalPort, " ", RemoteUrl),
            Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (LazyOwn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071 (Application Layer Protocol), T1105 (Ingress Tool Transfer)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by. The
// LazyOwn rows are its DNS C2 zone, the user agents of its beacon configuration and operator tools, its beacon route,
// file names and, once added, the addresses of exposed C2 servers.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "lazyown" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let URIs = toscalar(IOC | where type == "uri_string" and confidence in ("high", "medium") | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or DestinationHostName has_any (Domains)
            or RequestURL has_any (URIs)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication has_any (UAs), RequestClientApplication, DestinationHostName)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=iff(RemoteIP in (IPList), RemoteIP, RemoteUrl),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where MD5 in~ (MD5s)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=tolower(MD5), Detail=strcat(DeviceName, " ", FolderPath)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// LazyOwn beacons, operator clients and C2 answers in proxy, firewall and DNS logs
// Agentic attack detections by ThreatDefence (LazyOwn). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1071.004 (Application Layer Protocol: DNS), T1001.003 (Data Obfuscation: Protocol or Service Impersonation), T1572 (Protocol Tunneling)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the LazyOwn source code (grisuno/LazyOwn, reviewed at f4e54de9):
//  - The C2 serves beacons on <c2_malleable_route><client id> (GET for commands, POST for results; /gmail/v1/users/ in
//    the shipped payload.json, /api/v1/ when the key is empty) and always on /command/<id>, /api/poll/<id>, /report/,
//    /stage/beacon, /stage/config and /bof/<object>. A real Gmail API call goes to a Google host.
//  - Beacon configuration user agents: "...(Linux; LAzyOwnRedTeam 66_6)..." (user_agent_3 of the shipped payload.json)
//    and a Windows string with both Chrome/120.0.0.0 and Firefox/120.0 (BlackSandBeacon config the C2 builds).
//    The default beacon user agent is an old Chrome 58 string cut to Safari/537.3, widely copied, so it is kept to port 4444.
//  - The redirector the repository ships is a Cloudflare quick tunnel (*.trycloudflare.com) that forwards only /gmail/*,
//    /api/*, /command/* and /s/*.
//  - Operator tools: LazyOwn/1.0 on exploitalert.com searches, lazyown-depconfuse/1.0 on PyPI.
//  - The C2's DNS server answers the zone c2.lazyown.org with base64url command labels.
// HTTPS beacon traffic is visible only with TLS inspection or on the redirector.

let BeaconUAs = @"LAzyOwnRedTeam|Chrome/120\.0\.0\.0 Firefox/120\.0";
let OperatorUAs = dynamic(["LazyOwn/1.0"]);
let BeaconPaths = @"/(gmail/v1/users|command|api/poll)/[A-Za-z0-9_.-]+$|/stage/(beacon|config)$|/bof/[A-Za-z0-9_.-]+\.o$";
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(30d)
        | extend Path = tostring(parse_url(RequestURL).Path)
        | where (RequestURL has "/gmail/v1/users/" and not(DestinationHostName endswith "google.com" or DestinationHostName endswith "googleapis.com"))
            or RequestClientApplication matches regex BeaconUAs
            or RequestClientApplication in (OperatorUAs) or RequestClientApplication startswith "lazyown-depconfuse/"
            or (DestinationHostName endswith ".trycloudflare.com" and Path matches regex BeaconPaths)
            or (DestinationPort == 4444 and RequestClientApplication endswith "Chrome/58.0.3029.110 Safari/537.3")
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=strcat(DestinationHostName, ":", DestinationPort),
            Detail=RequestURL, UA=RequestClientApplication),
    (DnsEvents
        | where TimeGenerated > ago(30d)
        | where Name =~ "c2.lazyown.org" or Name endswith ".c2.lazyown.org"
        | project TimeGenerated, Source="DnsEvents", Src=ClientIP, Target=Name, Detail=strcat("QueryType ", QueryType), UA=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(30d)
        | where RemoteUrl endswith "c2.lazyown.org" or (RemoteUrl endswith ".trycloudflare.com" and InitiatingProcessCommandLine contains "/tmp/.dbus")
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=DeviceName, Target=RemoteUrl,
            Detail=InitiatingProcessCommandLine, UA="")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// MCP Kali Server running on a host you monitor
// Agentic attack detections by ThreatDefence (MCP Kali Server). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell), T1046 (Network Service Discovery)
// Example hunt for Defender XDR advanced hunting and Microsoft Sentinel. Test before alerting.
// From the MCP Kali Server source (Wh0am123/MCP-Kali-Server at 00154c05) and the Kali package mcp-kali-server (15136e98):
//  - API server: python3 server.py [--ip <ip>] [--port 5000], Flask, no authentication. Packaged as /usr/bin/kali-server-mcp, which
//    runs python3 server.py in /usr/share/mcp-kali-server/ as user _mcp-kali (kali-server-mcp.service). MCP client: client.py
//    --server http://<ip>:5000, packaged as /usr/bin/mcp-server (mcp-server.service).
//  - Every /health call runs which nmap, which gobuster, which dirb, which nikto. The Metasploit route runs
//    msfconsole -q -r /tmp/mks_msf_resource.rc. Upstream /api/command runs /bin/sh -c <command> under the server.
//  - Server log lines on stdout (journal and Syslog under systemd): "Starting Kali Linux Tools API Server on",
//    "Executing command: <command>". Client: "Starting MCP Kali server".
// The file name server.py and port 5000 are common; the package paths, the user and the resource file name need a code change.

let Window = 30d;
let ToolLookups = dynamic(["which nmap", "which gobuster", "which dirb", "which nikto"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any ("kali-server-mcp", "mcp-kali-server", "mks_msf_resource.rc")
            or AccountName == "_mcp-kali"
            or (ProcessCommandLine has "client.py" and ProcessCommandLine contains "--server http" and ProcessCommandLine contains ":5000")
            or (InitiatingProcessCommandLine has "server.py" and ProcessCommandLine in (ToolLookups))
            or (InitiatingProcessCommandLine has "server.py" and InitiatingProcessFileName startswith "python"
                and ProcessCommandLine startswith "/bin/sh -c ")
        | project Timestamp, DeviceName, Signal="MKS process, package, user or child of its API server", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName == "mks_msf_resource.rc" or FolderPath startswith "/usr/share/mcp-kali-server/"
            or FolderPath endswith "/kali-server-mcp.service" or FolderPath == "/etc/default/kali-server-mcp"
        | project Timestamp, DeviceName, Signal="MKS files", Detail=FolderPath, Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and InitiatingProcessCommandLine has "server.py"
            and (LocalPort == 5000 or InitiatingProcessCommandLine contains "--port")
            and InitiatingProcessFolderPath has "python"
        | project Timestamp, DeviceName, Signal="Python server.py listening (check for MKS: GET /health)", Detail=strcat(LocalIP, ":", LocalPort),
            Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (Syslog
        | where TimeGenerated > ago(Window)
        | where SyslogMessage has_any ("Kali Linux Tools API Server", "Starting MCP Kali server", "Initialized Kali Tools Client connecting to")
            or (ProcessName in ("kali-server-mcp", "python3") and SyslogMessage has "Executing command:")
        | project Timestamp=TimeGenerated, DeviceName=Computer, Signal="MKS log line", Detail=substring(SyslogMessage, 0, 300), Parent=ProcessName)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (MCP Kali Server). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. MCP Kali Server has no addresses or domains and sends no telemetry; its rows are its
// package paths, service and user names, its Metasploit resource file, its API routes and its log and health strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "mcp-kali-server" | project value=tostring(SearchKey), type, confidence, actor, source;
let HostStrings = toscalar(IOC | where type in ("file_path", "file_name", "account_name", "string") and confidence in ("high", "medium") | summarize make_list(value));
let WebStrings = toscalar(IOC | where type in ("string", "uri_string") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (HostStrings) or AccountName in (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (Syslog | where TimeGenerated > ago(30d)
        | where SyslogMessage has_any (WebStrings) or SyslogMessage has_any (HostStrings)
        | project TimeGenerated, Source="Syslog", Indicator=substring(SyslogMessage, 0, 200), Detail=strcat(Computer, " ", ProcessName)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (WebStrings)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=RequestURL, Detail=strcat(SourceIP, " -> ", DestinationHostName))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Indicator
| order by LastSeen desc

// MCP Kali Server API calls in firewall, proxy and network logs
// Agentic attack detections by ThreatDefence (MCP Kali Server). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Microsoft Sentinel and Defender XDR. Test and baseline before alerting.
// From the MCP Kali Server source (Wh0am123/MCP-Kali-Server at 00154c05):
//  - The API server is plain HTTP on 5000 with no authentication. The MCP client (python-requests) calls GET /health at start,
//    POST /api/command for raw commands and POST /api/tools/<nmap|gobuster|dirb|nikto|sqlmap|metasploit|hydra|john|wpscan|enum4linux>.
//    /mcp/tools/kali_tools/<name> and /mcp/capabilities are stub routes only MKS has.
//  - A call from another host means the operator exposed it (README: --ip 0.0.0.0, "openly hosting"), or someone else is using it.
// HexStrike and NyxStrike use the same route names on 8888, so this hunt keeps to port 5000 apart from the stub route.

let Routes = @"^/(api/command|api/tools/(nmap|gobuster|dirb|nikto|sqlmap|metasploit|hydra|john|wpscan|enum4linux)|health)$";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | extend Path = tostring(parse_url(RequestURL).Path)
        | where (DestinationPort == 5000 and Path matches regex Routes) or RequestURL contains "/mcp/tools/kali_tools/"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=strcat(DestinationIP, ":", DestinationPort), Detail=strcat(RequestMethod, " ", RequestURL)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where ActionType == "InboundConnectionAccepted" and LocalPort == 5000 and InitiatingProcessCommandLine has "server.py"
            and RemoteIPType != "Loopback"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=RemoteIP, Target=strcat(DeviceName, ":", LocalPort),
            Detail=substring(InitiatingProcessCommandLine, 0, 200))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10) by Source, Src, Target
| order by FirstSeen asc

// Mitsu running on a host you monitor
// Agentic attack detections by ThreatDefence (Mitsu). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1595.002 (Active Scanning: Vulnerability Scanning), T1552.001 (Unsecured Credentials: Credentials In Files)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Mitsu source code (ARCANGEL0/Mitsu at a4844932, PyPI package mitsu 1.5.2):
//  - Mitsu is a Python terminal app (console script "mitsu", or ./mitsu which runs uv run --project <checkout> mitsu).
//    Its process is python running .../bin/mitsu or python -m mitsu.
//  - With the Codex or Claude Code provider it starts, per turn, codex exec ... --config
//    mcp_servers.mitsu.url="http://127.0.0.1:<port>/<token>/mcp" --config developer_instructions="You are Mitsu: ..."
//    in <temp>/mitsu-codex-sessions/<id>, or claude -p ... --mcp-config {"mcpServers":{"mitsu":...}} --permission-mode
//    dontAsk --allowedTools mcp__mitsu__<tool> in <temp>/mitsu-claude-sessions/<id>. The connection check sends
//    "Reply exactly MITSU_OK.".
//  - Its shell tool runs /bin/bash -o pipefail -c <command> (60 s limit), or sudo -S -p "" -- /bin/bash -o pipefail
//    -c <command> with the password the operator typed into Mitsu. Armory tools (nmap, nuclei, sqlmap, ffuf, hydra,
//    netexec and 160 more) start directly under the mitsu process, without a shell.
//  - Managed SearXNG: docker run --name mitsu-searxng-<port> --publish 127.0.0.1:<port>:8080, volume mitsu-searxng-config.
//  - Files: ~/.local/share/mitsu/sessions/<32 hex>.json (conversation and Intel, credentials included),
//    <id>/artifacts/attack-surface-map.html and vulnerability-assessment-<UTC stamp>.html/.pdf, ~/.config/mitsu/
//    credentials.json (provider API keys), mcp_servers.json, host.json, ~/.local/share/mitsu/armory/<tool>/.

let Window = 30d;
let MitsuParent = (cmd:string) { cmd endswith "/bin/mitsu" or cmd endswith " -m mitsu" or cmd contains "/uv/tools/mitsu/" };
let Scanners = dynamic(["nmap", "masscan", "rustscan", "naabu", "httpx", "nuclei", "nikto", "sqlmap", "ffuf", "feroxbuster",
    "gobuster", "dirsearch", "wpscan", "whatweb", "wafw00f", "dalfox", "commix", "hydra", "medusa", "ncrack", "nxc", "netexec",
    "kerbrute", "certipy", "evil-winrm", "msfconsole", "searchsploit", "vulnx", "subfinder", "amass", "katana", "testssl"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "mcp_servers.mitsu.url="
            or ProcessCommandLine contains '"mcpServers":{"mitsu":{"type":"http"'
            or ProcessCommandLine contains "mcp__mitsu__intel_upsert_asset"
            or ProcessCommandLine contains "You are Mitsu: the operator"
            or ProcessCommandLine contains "You are Mitsu, a security assessment assistant."
            or ProcessCommandLine contains "MITSU_OK"
        | project Timestamp, DeviceName, AccountName, Signal="Model CLI started by Mitsu",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "/bin/bash -o pipefail -c " and MitsuParent(InitiatingProcessCommandLine)
        | project Timestamp, DeviceName, AccountName, Signal=iff(FileName =~ "sudo", "Mitsu shell tool with sudo", "Mitsu shell tool"),
            Detail=substring(ProcessCommandLine, 0, 300), Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName in~ (Scanners) and MitsuParent(InitiatingProcessCommandLine)
        | project Timestamp, DeviceName, AccountName, Signal="Armory tool started by Mitsu",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "mitsu-searxng-config" or ProcessCommandLine contains "--name mitsu-searxng-"
            or ProcessCommandLine contains "start mitsu-searxng-"
        | project Timestamp, DeviceName, AccountName, Signal="Mitsu SearXNG container",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/mitsu/sessions/" or FolderPath contains "/.config/mitsu/" or FolderPath contains "/mitsu/armory/"
            or FolderPath contains "/mitsu-codex-sessions/" or FolderPath contains "/mitsu-claude-sessions/"
            or FileName == ".mitsu-armory-managed"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessAccountName, InitiatingProcessFileName
        | project Timestamp, DeviceName, AccountName=InitiatingProcessAccountName, Signal="Mitsu session, configuration or report files",
            Detail=tostring(Files), Parent=InitiatingProcessFileName)
| order by Timestamp desc

// Mitsu reading your web pages, or running from your network: its user agents in web and proxy logs
// Agentic attack detections by ThreatDefence (Mitsu). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1594 (Search Victim-Owned Websites), T1593.002 (Search Open Websites/Domains: Search Engines)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Mitsu source code (ARCANGEL0/Mitsu at a4844932):
//  - The web_search MCP tool opens any URL the model passes with "Mitsu/0.1 (terminal assistant; public search)" and
//    Accept "text/html,text/plain,application/json,application/xml,*/*;q=0.5". The system prompt tells the model to
//    open every URL the operator gives this way before using curl or wget, so the first request a target sees is
//    often this one. The same user agent goes to search engines (html.duckduckgo.com, www.google.com, www.bing.com,
//    search.brave.com and others) and search APIs.
//  - "Mitsu updater" fetches https://pypi.org/pypi/mitsu/json when the operator opens the update panel.
//  - Scans through Armory tools carry those tools' own user agents; look for them from the same source address
//    shortly after a Mitsu page fetch.
// On a target, the source address is the operator's. In a proxy log, the source is a host of yours running Mitsu.

let PageUA = "Mitsu/0.1 (terminal assistant; public search)";
let UpdaterUA = "Mitsu updater";
union isfuzzy=true
    (W3CIISLog
        | where TimeGenerated > ago(30d)
        | extend UA = replace_string(csUserAgent, "+", " ")
        | where UA == PageUA
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (AzureDiagnostics
        | where TimeGenerated > ago(30d)
        | where Category == "ApplicationGatewayAccessLog"
        | where userAgent_s == PageUA
        | project TimeGenerated, Source=Category, Src=clientIP_s, Target=host_s, Detail=requestUri_s, UA=userAgent_s),
    (CommonSecurityLog
        | where TimeGenerated > ago(30d)
        | where RequestClientApplication in (PageUA, UpdaterUA)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 3) by Source, Src, Target
| order by FirstSeen asc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Mitsu). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1594 (Search Victim-Owned Websites), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Mitsu has no addresses, C2 or console of its own: its rows are user agents,
// command-line strings, file names and paths, and the model gateway it lists for "uncensored models" (low confidence).

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "mitsu" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Files = toscalar(IOC | where type == "file_name" | summarize make_list(value));
let Paths = toscalar(IOC | where type == "file_path" | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence == "high" | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication in (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=strcat(SourceIP, " ", RequestURL),
            Indicator=iff(RequestClientApplication in (UAs), RequestClientApplication, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=UA, Detail=strcat(cIP, " ", csUriStem)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteUrl,
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Files) or FolderPath has_any (Paths)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator="Mitsu string in command line",
            Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200)))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// Nebula running on a host you monitor
// Agentic attack detections by ThreatDefence (Nebula). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1610 (Deploy Container), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Nebula source code (BerylliumSec/nebula at 409bf4f9). It is a Python core with a Tauri desktop app that runs
// its agents' commands in a Kali container (Docker or Podman) or on the host:
//  - Core: nebula-core runtime-service --data-dir ... --manifest-sha256 ...; nebula-core desktop-connect; nebula-core
//    serve or headless; python -m nebula.v3.cli serve (container image); nebula-browserd
//  - Agent commands: docker exec ... nebula-runtime-<id> /usr/bin/python3 -c "...os.execv('/bin/bash',['/bin/bash',
//    '--noprofile','--norc','-c',sys.argv[2]])" /tmp/nebula-process-<id>.pid "<command>"
//  - Containers nebula-runtime-*, nebula-terminal-*, nebula-exec-*; image localhost/nebula-kali-headless
//  - Files: ~/.local/share/nebula/v3/, <app data>/io.nebula.security/core/, /tmp/nebula-process-*.pid,
//    /run/nebula/public-ip, /etc/cron.d/nebula-public-ip
// Commands that run inside its containers are seen only where the EDR covers container processes.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "os.execv('/bin/bash',['/bin/bash','--noprofile','--norc','-c',sys.argv[2]])"
            or ProcessCommandLine contains "/tmp/nebula-process-"
            or ProcessCommandLine contains "localhost/nebula-kali-headless"
            or ProcessCommandLine contains "--name=nebula-terminal-"
            or ProcessCommandLine contains "--name=nebula-runtime-"
            or ProcessCommandLine contains "/usr/local/lib/nebula-public-ip-update"
            or (ProcessCommandLine contains "nebula-core runtime-service" and ProcessCommandLine contains "--manifest-sha256")
            or ProcessCommandLine contains "nebula-core desktop-connect"
            or ProcessCommandLine contains "nebula-core serve"
            or ProcessCommandLine contains "nebula-core headless"
            or ProcessCommandLine contains "-m nebula.v3.cli"
            or FileName =~ "nebula-browserd"
        | project Timestamp, DeviceName, AccountName, Signal="Nebula process", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/.local/share/nebula/v3/" or FolderPath contains "/io.nebula.security/core/"
            or (FolderPath startswith "/tmp/nebula-process-" and FileName endswith ".pid")
            or FolderPath in~ ("/run/nebula/public-ip", "/etc/cron.d/nebula-public-ip", "/usr/local/share/nebula/security-tools.json")
            or FolderPath startswith "/var/lib/nebula-memory-runner/"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, AccountName=InitiatingProcessAccountName, FolderPath
        | project Timestamp, DeviceName, AccountName, Signal="Nebula files", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Nebula). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071 (Application Layer Protocol), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Nebula has no published infrastructure, so its rows are user agents, strings,
// file paths and the workspace icon hashes; the sweep looks for the user agents and the strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "nebula" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Strings = toscalar(IOC | where type in ("string", "file_name", "file_path", "docker_image") and confidence in ("high", "medium") | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication in~ (UAs) or RequestClientApplication has_any (UAs)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=RequestClientApplication, Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=replace_string(csUserAgent, "+", " "), Detail=strcat(cIP, " ", csUriStem)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where MD5 in~ (MD5s) or FolderPath has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=iff(MD5 in~ (MD5s), tolower(MD5), FolderPath),
            Detail=strcat(DeviceName, " ", FolderPath))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator
| order by LastSeen desc

// Nebula in web and proxy logs: its user agents, paired clients, tool callbacks and an exposed core
// Agentic attack detections by ThreatDefence (Nebula). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1133 (External Remote Services)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Nebula source code (BerylliumSec/nebula, reviewed at 409bf4f9):
//  - nebula-chat: its terminal client talking to a remote core; Nebula-Terminal/1: its Kali containers asking
//    api.ipify.org for their public address every five minutes; Nebula/3 knowledge-source-fetcher and -renderer:
//    pages an operator adds as project knowledge.
//  - /api/v1/auth/pairings/redeem: a browser or terminal client pairing with a core. In your own web server logs it
//    means you serve a Nebula core; through your proxy, someone paired with one.
//  - /api/v1/automation-processes/<id>/results: background tool results posted back to a core.
// The code sends no canary or marker to pentest targets: its scans look like the stock Kali tools.

let PairPath = "/api/v1/auth/pairings/redeem";
let ResultsPath = "/api/v1/automation-processes/";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in ("nebula-chat", "Nebula-Terminal/1") or UA startswith "Nebula/3 knowledge-source-"
            or csUriStem =~ PairPath or (csUriStem startswith ResultsPath and csUriStem endswith "/results")
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem), UA),
    (CommonSecurityLog
        | where RequestClientApplication in ("nebula-chat", "Nebula-Terminal/1") or RequestClientApplication startswith "Nebula/3 knowledge-source-"
            or RequestURL has PairPath or (RequestURL has ResultsPath and RequestURL has "/results")
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| extend Signal=case(UA == "nebula-chat", "Terminal client to a remote core",
    UA == "Nebula-Terminal/1", "Kali container public address check",
    UA startswith "Nebula/3 knowledge-source-", "Knowledge source fetch",
    Detail has PairPath, "Device pairing with a core",
    "Tool result posted to a core")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Signal, Source, Src, Target
| order by FirstSeen asc

// NeuroSploit on a host you monitor
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// NeuroSploit (JoasASantos/NeuroSploit, reviewed at 54d8e860) is a Rust harness with a Node.js web console on port 4173
// that has no login. No report of its use in a real intrusion was found on November 26, 2026, so this hunt looks for
// the software itself, from its source code:
//  - The binary neurosploit (neurosploit.exe), its C2 daemon "neurosploit c2 daemon --port 0 --dir <...>/.neurosploit/c2",
//    the containers neurosploit-kali and neurosploit-neo4j, and node running /tmp/ns_browser_prefetch.js.
//  - Coding agent CLIs started by neurosploit with approvals off: claude -p ... --dangerously-skip-permissions,
//    codex exec ... --dangerously-bypass-approvals-and-sandbox.
//  - Files: <cwd>/.neurosploit/ (keys.json, vault/, c2/), runs/ns-<unix time>-<target>/.
//  - The web console listening on 4173 (node), and the out-of-band listener on 8080 (neurosploit).
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Markers = dynamic(["c2 daemon --port 0 --dir", "neurosploit-kali", "neurosploit-neo4j", "ns_browser_prefetch.js", "neurosploit-mcp"]);
let NsProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("neurosploit", "neurosploit.exe") or ProcessCommandLine has_any (Markers)
        or (InitiatingProcessFileName in~ ("neurosploit", "neurosploit.exe")
            and ProcessCommandLine has_any ("--dangerously-skip-permissions", "--dangerously-bypass-approvals-and-sandbox"));
let NsDevices = NsProcesses | distinct DeviceName;
union isfuzzy=true
    (NsProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="NeuroSploit binary, C2 daemon, container or agent CLI child", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has_any ("/.neurosploit/c2/", @"\.neurosploit\c2\", "/.neurosploit/vault/", @"\.neurosploit\vault\")
            or FolderPath endswith "/.neurosploit/keys.json" or FolderPath endswith @"\.neurosploit\keys.json"
            or FolderPath =~ "/tmp/ns_browser_prefetch.js" or FolderPath matches regex @"[/\\]runs[/\\]ns-\d{10}-"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="NeuroSploit project store, vault, C2 state or run folder", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where (LocalPort == 4173 and InitiatingProcessFileName in~ ("node", "node.exe") and InitiatingProcessCommandLine has "server.js")
            or (InitiatingProcessFileName in~ ("neurosploit", "neurosploit.exe"))
        | summarize Ports=make_set(LocalPort, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="NeuroSploit console (4173) or listener opened by neurosploit", Detail=strcat(InitiatingProcessFileName, " ", tostring(Ports)))
| extend KnownNeuroSploitDevice = DeviceName in (NsDevices)
| order by Timestamp desc

// NeuroSploit testing you: its user agent, probe path, canaries and out-of-band callbacks in web, proxy and DNS logs
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the NeuroSploit source code (JoasASantos/NeuroSploit, reviewed at 54d8e860):
//  - The harness's own requests carry User-Agent NeuroSploit/<version> and the header X-NeuroSploit-Scan (headers are
//    rarely logged; the user agent is). Its first probe requests /nrsplt_baseline_404_check_9x7.
//  - Canaries are NEUROSPLOIT<kind><12 hex> with the sigil in upper case: /NEUROSPLOITsub<hex> soft-404 checks and
//    NEUROSPLOITnsxss<hex> in XSS payloads. Open redirect tests use neurosploit.example; SSRF tests without an
//    out-of-band domain use http://oob.invalid/. Sign-ups use nrsplt_<rand>@example.test (an example in the prompt).
//  - Out-of-band payloads make your servers look up or fetch <token>.<operator domain>, where the token starts with
//    neurosploit. neurosploitai.github.io is the project's documentation site and is left out.
// The browser fallback user agent (Chrome 125 on Windows) is a real browser string, so it is not used here.

let Window = 30d;
let PathMarkers = dynamic(["nrsplt_baseline_404_check_9x7", "neurosploit.example", "oob.invalid", "nrsplt_"]);
let IsOob = (h:string) { tolower(h) startswith "neurosploit" and not(tolower(h) startswith "neurosploitai.") };
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA startswith "NeuroSploit/" or UA has "NeuroSploit-WebShell/" or csUriStem has_any (PathMarkers) or csUriQuery has_any (PathMarkers)
            or csUriStem has_cs "NEUROSPLOIT" or csUriQuery has_cs "NEUROSPLOIT"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestClientApplication startswith "NeuroSploit" or RequestClientApplication has "NeuroSploit-WebShell/"
            or RequestURL has_any (PathMarkers) or RequestURL has_cs "NEUROSPLOIT" or IsOob(DestinationHostName)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (DnsEvents | where TimeGenerated > ago(Window)
        | where IsOob(Name)
        | project TimeGenerated, Source="DnsEvents (out-of-band lookup)", Src=ClientIP, Target=Name, Detail=Name, UA=""),
    (DeviceNetworkEvents | where Timestamp > ago(Window)
        | where IsOob(RemoteUrl)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents (out-of-band callback)", Src=DeviceName, Target=RemoteUrl,
            Detail=InitiatingProcessCommandLine, UA="")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// NeuroSploit C2 beacons, NSUpdate persistence and web shells on hosts it compromised
// Agentic attack detections by ThreatDefence (NeuroSploit). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1053.005 (Scheduled Task/Job: Scheduled Task), T1547.001 (Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder), T1053.003 (Scheduled Task/Job: Cron), T1543.002 (Create or Modify System Process: Systemd Service), T1505.003 (Server Software Component: Web Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the NeuroSploit C2 code (harness/src/c2/templates.rs at 54d8e860), which is off until the operator enables it:
//  - Beacons POST to http://<callback>:<port>/api/beacon (bash adds ?format=sh) with the header X-Implant-Token.
//    CyberStrikeAI's implant uses the same header name, with /check_in and /tasks instead of /api/beacon.
//  - Windows persistence: schtasks /Create /F /SC ONLOGON /TN "NSUpdate" or a Run value NSUpdate, both starting
//    powershell -NoProfile -ExecutionPolicy Bypass -EncodedCommand <beacon>.
//  - Linux persistence: @reboot crontab entry, "# NSUpdate" in ~/.bashrc, or ~/.config/systemd/user/nsupdate.service.
//  - Web shells start with the comment "NeuroSploit WebShell"; generated names are webshell-<ms>.<php|aspx|asp|jsp>;
//    the manager sends User-Agent "Mozilla/5.0 (compatible; NeuroSploit-WebShell/1.0)".

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(Window)
        | where (ProcessCommandLine has "X-Implant-Token" and ProcessCommandLine has "/api/beacon")
            or (ProcessCommandLine has "schtasks" and ProcessCommandLine has "NSUpdate")
            or (ProcessCommandLine has @"CurrentVersion\Run" and ProcessCommandLine has "NSUpdate")
            or ProcessCommandLine has "nsupdate.service" or ProcessCommandLine has "# NSUpdate"
        | project TimeGenerated=Timestamp, DeviceName, Signal="NeuroSploit beacon or persistence command", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceRegistryEvents | where Timestamp > ago(Window)
        | where RegistryKey endswith @"\CurrentVersion\Run" and RegistryValueName =~ "NSUpdate"
        | project TimeGenerated=Timestamp, DeviceName, Signal="Run value NSUpdate", Detail=RegistryValueData),
    (DeviceFileEvents | where Timestamp > ago(Window)
        | where FileName =~ "nsupdate.service" or FileName matches regex @"^webshell-\d{13}\.(php|aspx|asp|jsp)$"
            or FileName matches regex @"^beacon-\d{13}\.(sh|py|ps1|php)$"
        | project TimeGenerated=Timestamp, DeviceName, Signal="NeuroSploit unit, web shell or beacon file name", Detail=FolderPath),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") has "NeuroSploit-WebShell/" or csUriQuery has "pass=ns_pass"
        | project TimeGenerated, DeviceName=csHost, Signal="Web shell manager request", Detail=strcat(csMethod, " ", csUriStem, " from ", cIP))
| order by TimeGenerated desc

// numasec running on a host you monitor
// Agentic attack detections by ThreatDefence (numasec). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1219 (Remote Access Tools)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the numasec source code (FrancescoStabile/numasec at 1237a2f). numasec is OpenCode renamed, with security tools
// added, and ships as a Bun-compiled binary:
//  - npm install -g numasec runs numasec from node_modules/numasec-<os>-<arch>/bin/numasec (numasec.exe on Windows);
//    the Docker image is francescostabile/numasec (README; unverified on Docker Hub) with /usr/local/bin/numasec.
//  - numasec serve (and acp, or the TUI with --hostname/--mdns) opens an HTTP API on 127.0.0.1:4096 by default. With
//    --hostname 0.0.0.0 or --mdns and no NUMASEC_SERVER_PASSWORD it gives shell, file and agent access to anyone.
//  - Its out-of-band tool runs interactsh-client -json -o <data>/numasec/log/int_<hex>.jsonl -v.
//  - It writes <workspace>/.numasec/operation/<slug>/ (ledger, facts, evidence, deliverables) and
//    ~/.local/share/numasec/numasec.db.
// Folder names, the port and the server options are inherited from OpenCode with the name changed.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("numasec", "numasec.exe")
            or ProcessCommandLine contains "install -g numasec" or ProcessCommandLine contains "add -g numasec"
            or ProcessCommandLine contains "francescostabile/numasec"
            or (FileName in~ ("interactsh-client", "interactsh-client.exe") and (ProcessCommandLine contains "/numasec/log/int_" or ProcessCommandLine contains @"\numasec\log\int_"))
        | extend Exposed = FileName in~ ("numasec", "numasec.exe")
            and (ProcessCommandLine contains "--hostname 0.0.0.0" or ProcessCommandLine contains "--hostname=0.0.0.0" or ProcessCommandLine contains "--mdns")
        | project Timestamp, DeviceName, Signal=iff(Exposed, "numasec server on all interfaces", "numasec process or install"),
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and InitiatingProcessFileName in~ ("numasec", "numasec.exe")
        | project Timestamp, DeviceName, Signal=iff(LocalIP in ("127.0.0.1", "::1"), "numasec API listening on loopback", "numasec API listening on a network address"),
            Detail=strcat(LocalIP, ":", LocalPort), Parent=InitiatingProcessCommandLine),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/.numasec/operation/" or FolderPath contains @"\.numasec\operation\"
            or (FileName in~ ("numasec.db", "interact-sessions.json") and (FolderPath contains "/numasec/" or FolderPath contains @"\numasec\"))
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".numasec")[0])
        | project Timestamp, DeviceName, Signal="numasec operation or data files", Detail=strcat(Folder, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// numasec testing you: its probe user agents and markers in web and proxy logs
// Agentic attack detections by ThreatDefence (numasec). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1595.003 (Active Scanning: Wordlist Scanning), T1046 (Network Service Discovery)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the numasec source code (FrancescoStabile/numasec at 1237a2f). These strings are hard-coded in numasec's own
// probes, not chosen by the model:
//  - appsec_probe sends User-Agent numasec-appsec-probe/1.2 with ' OR 1=1--, <script>numasec-xss</script>, a login
//    as numasec-probe@example.invalid / numasec-probe and Origin https://evil.example (src/tool/appsec-probe.ts).
//  - The directory fuzzer first requests /numasec_404_check_<epoch ms>, then its wordlist (src/scanner/dir-fuzzer.ts:123).
//  - The service prober sends GET / with only the header Host: target (src/scanner/service-prober.ts:25).
//  - The page fetch tool retries with the user agent numasec after a Cloudflare challenge (src/tool/webfetch.ts:99).
// Operator side (TLS inspection only): numasec-knowledge-broker/1.2 to NVD, CISA, FIRST, OSV and GitHub advisories, and
// numasec/<version> to model APIs and models.dev show which of your machines runs numasec.

let Markers = @"numasec_404_check_|numasec-xss|numasec-probe@";
let TargetUAs = dynamic(["numasec", "numasec-appsec-probe/1.2"]);
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA in~ (TargetUAs) or UA startswith "numasec-appsec-probe/" or csUriStem matches regex Markers or csUriQuery matches regex Markers
            or (csHost == "target" and csUriStem == "/")
        | project TimeGenerated, Source="W3CIISLog", Side="target", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery, " ", scStatus), UA),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication in~ (TargetUAs) or RequestClientApplication startswith "numasec-appsec-probe/" or RequestURL matches regex Markers
        | project TimeGenerated, Source="CommonSecurityLog", Side="target", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication startswith "numasec-knowledge-broker/" or RequestClientApplication startswith "numasec/"
        | project TimeGenerated, Source="CommonSecurityLog", Side="operator", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Side, Src, Target
| order by FirstSeen asc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (numasec). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. The numasec rows are strings from its source code: user agents, probe markers,
// file paths and the image name. It has no published campaign addresses.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "numasec" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let URIs = toscalar(IOC | where type in ("uri_string", "string") and confidence in ("high", "medium") | summarize make_list(value));
let Files = toscalar(IOC | where type in ("file_path", "file_name") | summarize make_list(value));
let Images = toscalar(IOC | where type == "docker_image" | summarize make_list(value));
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has_any (UAs) or csUriStem has_any (URIs) or csUriQuery has_any (URIs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=iff(UA has_any (UAs), UA, strcat(csUriStem, "?", csUriQuery)), Detail=strcat(cIP, " -> ", csHost)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL has_any (URIs)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=iff(RequestClientApplication has_any (UAs), RequestClientApplication, RequestURL),
            Detail=strcat(SourceIP, " -> ", DestinationHostName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Files) or FileName in~ (Files)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=DeviceName),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Images)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator
| order by LastSeen desc

// NyxStrike server, MCP client or local model on a host you monitor
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the NyxStrike source code (CommonHuman-Lab/nyxstrike, reviewed at 3ac7449, version 1.9.0):
//  - The server is nyxstrike_server.py, run from the virtual environment nyxstrike-env by nyxstrike.sh, on
//    127.0.0.1:8888 by default (NYXSTRIKE_HOST, NYXSTRIKE_PORT). Since 1.8.0 it refuses any other address unless
//    NYXSTRIKE_API_TOKEN is set. The Docker image runs it from /opt/nyxstrike in a container named nyxstrike.
//  - Every tool runs through /bin/sh -c with the Python server as parent, prefixed with "nice -n 10" when CPU is above 85%.
//  - When its tool list is older than an hour, /health or /web-dashboard runs "which <tool>" (no shell) for about 150
//    tools, 20 at a time.
//  - At start-up it fetches raw.githubusercontent.com/CommonHuman-Lab/nyxstrike/master/config.py (version check).
//  - With -ai or -ai-small, nyxstrike.sh pulls huihui_ai/gemma-4-abliterated:e4b or huihui_ai/qwen3.5-abliterated:2B into
//    Ollama and creates the model nyxstrike-ai.
//  - Files: .nyxstrike_data/ (nyxstrike.db, sessions/, run_history.json, config/cred_key, config/config_local.json),
//    nyxstrike.log, /tmp/security_screenshot_<epoch>.png.
// HexStrike hunt 03 looks for "sh -c which"; NyxStrike runs which directly, so use this hunt for NyxStrike.

let Window = 30d;
let Names = dynamic(["nyxstrike_server.py", "nyxstrike_mcp.py", "nyxstrike.sh", "/nyxstrike-env/"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Names) or InitiatingProcessCommandLine has "nyxstrike_server.py"
        | summarize Events=count(), Children=make_set(FileName, 30), Commands=make_set(substring(ProcessCommandLine, 0, 200), 15),
            Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="NyxStrike process or a tool it started", Detail=strcat(tostring(Children), " ", tostring(Commands)), Parent),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where FileName == "which" and InitiatingProcessFileName startswith "python"
        | summarize Lookups=dcount(ProcessCommandLine), Sample=make_set(ProcessCommandLine, 10), Timestamp=min(Timestamp)
            by DeviceName, Parent=InitiatingProcessCommandLine, Minute=bin(Timestamp, 1m)
        | where Lookups >= 40
        | project Timestamp, DeviceName, Signal="which burst from a Python server (NyxStrike tool availability check)", Detail=strcat(Lookups, " tools: ", tostring(Sample)), Parent),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "ollama" and ProcessCommandLine has_any ("nyxstrike-ai", "gemma-4-abliterated", "qwen3.5-abliterated")
        | project Timestamp, DeviceName, Signal="Ollama model used by NyxStrike", Detail=substring(ProcessCommandLine, 0, 300), Parent=InitiatingProcessCommandLine),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 8888 and InitiatingProcessCommandLine has "nyxstrike_server.py"
        | project Timestamp, DeviceName, Signal="NyxStrike server listening", Detail=LocalIP, Parent=InitiatingProcessCommandLine),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.nyxstrike_data/" or FileName == "nyxstrike.log" or FolderPath startswith "/tmp/security_screenshot_"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="NyxStrike data, log or screenshot", Detail=tostring(Files), Parent)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.
// No NyxStrike infrastructure has been published, so these rows are fingerprints of the software: its user agents,
// strings and file names. Rows shared with HexStrike carry both framework names.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "nyxstrike" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where SourceIpAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Indicator=SourceIpAddress, Detail=strcat(EventName, " ", UserIdentityArn)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication has_any (UAs), RequestClientApplication, DestinationHostName)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where cIP in (IPList) or replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=iff(cIP in (IPList), cIP, replace_string(csUserAgent, "+", " ")), Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=iff(RemoteIP in (IPList), RemoteIP, RemoteUrl),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where MD5 in~ (MD5s)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=tolower(MD5), Detail=strcat(DeviceName, " ", FolderPath)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// NyxStrike testing you, or a NyxStrike server used through your proxy: user agents, probe markers and server paths
// Agentic attack detections by ThreatDefence (NyxStrike). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the NyxStrike source code (CommonHuman-Lab/nyxstrike, reviewed at 3ac7449):
//  - User agents hard-coded in NyxStrike: NyxStrike/1.0 (decision engine, a HEAD then GET of the target),
//    Security-HTTP-Framework/1.0 (Advanced Security Testing) and Security-BrowserAgent/1.0 (Security Testing).
//    HexStrike's were HexStrike-HTTP-Framework/ and HexStrike-BrowserAgent/, so the HexStrike hunts miss these.
//  - commonhuman-core/openapi-discover: its OpenAPI discovery requests /openapi.json, /swagger.json, /api-docs, /docs ...
//  - <xssTest123>: the reflection probe its browser agent puts into GET forms, sent with python-requests.
//  - StingXSS_<6> and BreachSQL_<6>: markers of the StingXSS and BreachSQL scanners NyxStrike installs. They also run on
//    their own, so a hit on those alone means the scanner, not necessarily NyxStrike.
//  - From the operator side: the version check to raw.githubusercontent.com/CommonHuman-Lab/nyxstrike/ and requests to
//    a NyxStrike server's /web-dashboard and /api/intelligence/ai-*-session.
// Mozilla/5.0 (Compatible Exploit) in NyxStrike's generated exploits is shared with HexStrike and is in its hunts.

let UAs = dynamic(["NyxStrike/", "Security-HTTP-Framework/", "Security-BrowserAgent/", "commonhuman-core/openapi-discover"]);
let Markers = @"xssTest123|StingXSS_|BreachSQL_|stingxss_redir_marker|stingxss_jsonp_probe|stingxss-crlf-detected";
let ServerPaths = @"raw\.githubusercontent\.com/CommonHuman-Lab/nyxstrike/|:8888/web-dashboard|:8888/api/intelligence/ai-(recon|profiling|vuln|osint|followup)-session";
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has_any (UAs) or csUriQuery matches regex Markers or csUriStem matches regex Markers
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL matches regex Markers or RequestURL matches regex ServerPaths
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (SigninLogs | where TimeGenerated > ago(90d)
        | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Src=IPAddress, Target=AppDisplayName, Detail=UserPrincipalName, UA=UserAgent),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Src=SourceIpAddress, Target=EventSource, Detail=EventName, UA=UserAgent)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

