// PentAGI server and worker containers on a host you monitor
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the PentAGI source code. Someone running PentAGI on your own hosts is an authorized tester, an insider or an
// intruder staging from your network.
//  - Every agent command runs in the flow's Kali container through a wrapper that ignores hangups and marks the process by
//    raising its oom_score_adj: sh -c 'trap "" HUP; read -r adj 2>/dev/null </proc/self/oom_score_adj && echo $((adj + 1))
//    2>/dev/null >/proc/self/oom_score_adj; exec sh -c "$0"' <command> (backend/pkg/docker/flow_commands.go:9-19).
//  - Worker containers are named pentagi-terminal-<flow id>, use /work as working folder and a pentagi-terminal-<id>-data
//    volume, and run vxcontrol/kali-linux by default (backend/pkg/tools/terminal.go:27, backend/pkg/docker/client.go:33-34,
//    backend/pkg/config/config.go:67).
//  - Each flow publishes two ports from 28000 on every interface (backend/pkg/docker/client.go:35-44, 121-131).
//  - The server runs as root with the Docker socket mounted, listens on 8443, and calls update.pentagi.com every three hours
//    (docker-compose.yml, backend/pkg/server/update/update.go).
// The wrapper, container prefix and update check need a code change to remove; ports and images are configuration.

let Window = 30d;
let PortsBase = 28000;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine contains "/proc/self/oom_score_adj" and ProcessCommandLine contains "exec sh -c")
            or ProcessCommandLine has_any ("pentagi-terminal-", "vxcontrol/kali-linux", "vxcontrol/pentagi", "vxcontrol/scraper")
        | project Timestamp, DeviceName, Signal="process", Detail=substring(ProcessCommandLine, 0, 300),
            Actor=InitiatingProcessFileName, Account=AccountName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort between (PortsBase .. PortsBase + 1999)
            and InitiatingProcessFileName in~ ("docker-proxy", "dockerd", "containerd")
        | summarize Ports=make_set(LocalPort, 20), Listeners=dcount(LocalPort), Timestamp=min(Timestamp) by DeviceName
        | where Listeners >= 2
        | project Timestamp, DeviceName, Signal="worker ports published in 28000-29999", Detail=tostring(Ports),
            Actor="docker", Account=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has_any ("update.pentagi.com", "support.pentagi.com")
        | summarize Calls=count(), Timestamp=min(Timestamp), Actor=take_any(InitiatingProcessFileName) by DeviceName, RemoteUrl
        | project Timestamp, DeviceName, Signal="PentAGI update check", Detail=strcat(RemoteUrl, " x", Calls), Actor, Account="")
| order by Timestamp desc

// Every page fetched twice at once: PentAGI's browser tool reading your application
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1594 (Search Victim-Owned Websites)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the PentAGI source code. The browser tool hands each page to the scraper service twice in parallel: once for the
// content (/html, /markdown or /links) and once for a full-page screenshot (/screenshot?fullPage=true), started together
// in two goroutines (backend/pkg/tools/browser.go). The scraper is a headless browser, so your logs see the same URL
// requested twice within a second or two from the same address, page after page, often followed by the assets a
// full-page render loads. Elastic noted the same pattern. Browsers and crawlers rarely request one HTML page twice at
// the same moment.
// Exclude your uptime monitors and link-preview services, which can produce the same pairs.

let Window = 7d;
let Static = @"(?i)\.(js|css|png|jpe?g|gif|svg|ico|woff2?|ttf|map|webp)(\?|$)";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window) and RequestMethod == "GET" and isnotempty(RequestURL)
        | project TimeGenerated, Src=SourceIP, Host=DestinationHostName, Url=RequestURL, UA=RequestClientApplication),
    (W3CIISLog | where TimeGenerated > ago(Window) and csMethod == "GET"
        | project TimeGenerated, Src=cIP, Host=csHost, Url=strcat(csUriStem, "?", csUriQuery), UA=csUserAgent)
| where not(Url matches regex Static)
| summarize Hits=count(), First=min(TimeGenerated), Last=max(TimeGenerated), UAs=make_set(UA, 3) by Src, Host, Url, Second2=bin(TimeGenerated, 2s)
// The same page twice inside two seconds
| where Hits == 2
| summarize Pairs=count(), Pages=dcount(Url), SampleURLs=make_set(Url, 10), UAs=make_set(UAs, 5),
    FirstSeen=min(First), LastSeen=max(Last) by Src, Host, Hour=bin(First, 1h)
// Several different pages read the same way within an hour
| where Pages >= 5
| order by Pages desc

// PentAGI console and update traffic in your outbound proxy logs
// Agentic attack detections by ThreatDefence (PentAGI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Needs a proxy that records full URLs (TLS inspection). Test before alerting.
// From the PentAGI source code. People on your network driving a remote PentAGI console, or a PentAGI host behind your
// proxy, leave requests a proxy can name:
//  - The console API under /api/v1: /api/v1/info answers without a session and reports the configured model providers,
//    /api/v1/graphql carries the flows, /api/v1/graphql/playground and the Swagger UI ("PentAGI Swagger API") exist in
//    developer builds (backend/pkg/server/router.go:72, 297-301, 522). Default port 8443, HTTPS with a PentAGI CA certificate.
//  - The update check: POST https://update.pentagi.com/api/v1/proxy/updates/pentagi/check every 3 hours, with a
//    proof-of-work ticket fetched first (backend/pkg/server/update/update.go:52).
// Ports and the update interval are configuration. The API paths and the update endpoint need a code change.

let Window = 30d;
CommonSecurityLog
| where TimeGenerated > ago(Window) and isnotempty(RequestURL)
| extend Signal = case(
    RequestURL contains "update.pentagi.com" or DestinationHostName =~ "update.pentagi.com", "PentAGI update check",
    RequestURL contains "/api/v1/proxy/updates/pentagi/check", "PentAGI update check through a custom host",
    RequestURL contains "/api/v1/graphql/playground", "PentAGI GraphQL playground",
    RequestURL contains "/api/v1/info" and (DestinationPort in (8443, 8666, 8765) or RequestURL contains ":8443/"), "PentAGI console info endpoint",
    RequestURL contains "/api/v1/graphql" and (DestinationPort in (8443, 8666, 8765) or RequestURL contains ":8443/"), "PentAGI console GraphQL",
    "")
| where isnotempty(Signal)
| summarize Requests=count(), Signals=make_set(Signal), Destinations=make_set(DestinationHostName, 10),
    SampleURLs=make_set(RequestURL, 10), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by SourceIP, SourceUserName
| order by array_length(Signals) desc, Requests desc

// pentest-ai on a host you monitor
// Agentic attack detections by ThreatDefence (pentest-ai). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// pentest-ai (0xSteph/pentest-ai, PyPI ptai) is a Python CLI and MCP server that runs web, API, AD and cloud probes,
// driven by a model or by an AI coding client. No report of its use in a real intrusion was found, so this hunt looks
// for the software itself, from its source code at b51ec6ee:
//  - The console scripts ptai and pentest-ai (start, mcp, serve), the registration claude mcp add ... pentest-ai --
//    <path>/ptai mcp, the image ghcr.io/0xsteph/pentest-ai and pip or pipx installs of ptai.
//  - Files: ~/.pentest-ai/install_id (the id in its user agent), mcp-token, aup-consent.txt, credentials,
//    programs/<name>.toml, and ~/.local/share/pentest-ai/findings.db.
//  - Connections to telemetry.pentestai.xyz (opt-in telemetry) and app.pentestai.xyz (cloud sync).
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Cli = dynamic(["/bin/ptai start ", "/bin/ptai mcp", "/bin/ptai serve", "/bin/pentest-ai start ", "/bin/pentest-ai mcp",
    "/bin/pentest-ai serve", " pentest-ai -- ptai mcp", "ghcr.io/0xsteph/pentest-ai", "pipx install ptai", "pip install ptai"]);
let PtaiProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("ptai.exe", "pentest-ai.exe") or ProcessCommandLine has_any (Cli);
union isfuzzy=true
    (PtaiProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="pentest-ai CLI, MCP server, container or install", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath has ".pentest-ai" and FileName in~ ("install_id", "mcp-token", "aup-consent.txt", "credentials"))
            or FolderPath has "/.pentest-ai/programs/" or FolderPath has @"\.pentest-ai\programs\"
            or (FileName =~ "findings.db" and FolderPath has "pentest-ai")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="pentest-ai install id, token, program file or findings database", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl in~ ("telemetry.pentestai.xyz", "app.pentestai.xyz")
        | summarize Urls=make_set(RemoteUrl, 5), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="pentest-ai telemetry or cloud sync", Detail=strcat(tostring(Urls), " ", InitiatingProcessCommandLine))
| order by Timestamp desc

// pentest-ai testing you: its user agent, install id, probe path and canaries in web and proxy logs
// Agentic attack detections by ThreatDefence (pentest-ai). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the pentest-ai source code (0xSteph/pentest-ai, reviewed at b51ec6ee):
//  - Its own HTTP code sends User-Agent pentest-ai/<version> (compatible; rv:<install id>; +https://pentestai.xyz) and
//    X-Request-ID: 7a3f9c21-4b08-4e11-9c02-<install id>. The install id is 12 hex characters created once per machine,
//    so it ties together scans from one install across targets and source addresses. Headers other than the user
//    agent are rarely logged. API discovery uses ptai-api-discovery/<version>, authenticated scans pentest-ai/authscan.
//  - --intensity stealth swaps the user agent for a browser string on most probes; the canaries below stay.
//  - Soft-404 path /this-path-definitely-does-not-exist-ptai-canary; open redirect canary r.pentestai.xyz; oracle
//    canaries <ptaiRX9173>, <ptaiSX9173>, ptaictlZ9173, ptaicanary, ptai_xss_probe; canary hosts ptai-canary.example,
//    ptai-pkce-canary.example. A canary means a finding was being proven: look at what the same source sent just before.

let Window = 30d;
let Markers = dynamic(["this-path-definitely-does-not-exist-ptai-canary", "ptai-ssrf-control-404", "r.pentestai.xyz", "ptaiRX9173",
    "ptaiSX9173", "ptaictlZ9173", "ptaicanary", "ptai_xss_probe", "ptai-canary.example", "ptai-pkce-canary.example"]);
let IsPtaiUA = (ua:string) { ua startswith "pentest-ai/" or ua startswith "ptai-api-discovery/" };
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where IsPtaiUA(UA) or csUriStem has_any (Markers) or csUriQuery has_any (Markers)
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where IsPtaiUA(RequestClientApplication) or RequestURL has_any (Markers)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| extend InstallId=extract(@"rv:([0-9a-f]{8,12})", 1, UA)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5), Targets=make_set(Target, 10), InstallIds=make_set(InstallId, 5) by Source, Src
| order by FirstSeen asc

// Pentest Copilot running on a host you monitor
// Agentic attack detections by ThreatDefence (Pentest Copilot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Pentest Copilot source code (bugbasesecurity/pentest-copilot at cd512edd). It is a Node.js web application
// that runs its agent's commands on the backend container, a Kali container or an SSH host:
//  - Every agent command: mkdir -p -- <folder> && cd -- <folder> && "${SHELL:-$(command -v bash || command -v sh)}" -l -c '<cmd>'
//  - Python: python3 << 'PYTHON_SCRIPT_EOF' ... PYTHON_SCRIPT_EOF
//  - Subscription models: codex exec ... or claude --print ... with "You are an inference transport inside Pentest Copilot"
//  - Kali container: reads /run/pentest-copilot.env; work folder check .pentest-copilot-write-test; certutil adds
//    "Pentest Copilot Burp CA"
//  - Files: /kali-data/workspaces/<uuid>/, /kali-data/vpn-profiles/, /tmp/pentest-codex-*, /tmp/pentest-claude-*,
//    /srv/data/model-registry.json, /srv/data/burp-ca/burp-ca.der
// Run it on the Kali box or SSH host as well as the Docker host: the commands run there.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains '${SHELL:-$(command -v bash || command -v sh)}" -l -c'
            or ProcessCommandLine contains "<< 'PYTHON_SCRIPT_EOF'"
            or ProcessCommandLine contains "You are an inference transport inside Pentest Copilot"
            or ProcessCommandLine contains "/run/pentest-copilot.env"
            or ProcessCommandLine contains ".pentest-copilot-write-test"
            or ProcessCommandLine contains "Pentest Copilot Burp CA"
        | project Timestamp, DeviceName, AccountName, Signal="Pentest Copilot command", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath contains "/kali-data/workspaces/" or FolderPath contains "/kali-data/vpn-profiles/"
            or FolderPath contains "/pentest-codex-" or FolderPath contains "/pentest-claude-"
            or FileName =~ ".pentest-copilot-write-test"
            or (FolderPath startswith "/srv/data/" and FileName in~ ("model-registry.json", "burp-ca.der"))
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, AccountName=InitiatingProcessAccountName, FolderPath
        | project Timestamp, DeviceName, AccountName, Signal="Pentest Copilot files", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Pentest Copilot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071 (Application Layer Protocol), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Pentest Copilot has no published infrastructure, so its rows are a user agent,
// strings, file names and the console icon hash; the sweep looks for the user agent and the strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "pentest-copilot" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Strings = toscalar(IOC | where type in ("string", "file_name", "file_path") and confidence in ("high", "medium") | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=RequestClientApplication, Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=replace_string(csUserAgent, "+", " "), Detail=strcat(cIP, " ", csUriStem)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where MD5 in~ (MD5s) or FolderPath has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=iff(MD5 in~ (MD5s), tolower(MD5), FolderPath),
            Detail=strcat(DeviceName, " ", FolderPath))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator
| order by LastSeen desc

// Pentest Copilot in web and proxy logs: its CTFd user agent, its console API and its MCP token
// Agentic attack detections by ThreatDefence (Pentest Copilot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Pentest Copilot source code (bugbasesecurity/pentest-copilot, reviewed at cd512edd):
//  - It fetches CTFd pages (/, /login, /challenges) and posts the CTFd login with the user agent PentestCopilot/1.0.
//  - Its console calls /api/auth/registration-status, without a login, on the login and registration pages. In your
//    own web server logs that means you serve a Pentest Copilot console; through your proxy, someone opened one.
//  - Its MCP endpoint is /mcp with bearer tokens pc_mcp_<48 hex>; it refuses any Host other than localhost.
// The code sends no canary or marker to pentest targets: its scans look like the stock Kali tools.

let ConsolePath = "/api/auth/registration-status";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA startswith "PentestCopilot/" or csUriStem =~ ConsolePath
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", csUriStem), UA),
    (CommonSecurityLog | where RequestClientApplication startswith "PentestCopilot/" or RequestURL has ConsolePath
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| extend Signal=iff(UA startswith "PentestCopilot/", "CTFd client user agent", "Pentest Copilot console API")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Signal, Source, Src, Target
| order by FirstSeen asc

// Pentest Harness web UI, sandboxed agent shell or home folder on a host you monitor
// Agentic attack detections by ThreatDefence (Pentest Harness). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the Pentest Harness source code (S1N6H/pentest-harness, reviewed at 4638f38, September 11, 2026), a rebrand of
// the dsh agent harness. Branches marked "dsh family" also find the upstream harness and its other forks:
//  - "pnpm dsh web" runs "node --import tsx/esm apps/cli/src/bin.ts web"; a build runs apps/cli/lib/bin.js or
//    apps/cli/lib/index.js. The web UI listens on 127.0.0.1:2323 with no login (dsh family).
//  - Every shell command the model runs is "<bash> -c <command>" inside a sandbox wrapper, child of node:
//    bwrap --ro-bind / / --dev /dev --unshare-pid --proc /proc --die-with-parent ... (Linux), the bundled
//    @pentest-harness/node-addon-landlock-run-<platform>/bin/landlock-run --ro / --rw /dev/null ... (Linux fallback),
//    sandbox-exec -p "(version 1) (allow default) (deny file-write*) ..." (macOS). With
//    DSH_PERMISSION_MODE=danger-full-access node starts bash -c directly.
//  - Home folder ~/.dsh: .credentials.yaml (model keys), .anonymous-user-id, settings.yaml,
//    sessions/<project>/<id>/session.jsonl (dsh family).

let Window = 30d;
let Wrappers = dynamic(["--ro-bind / / --dev /dev --unshare-pid --proc /proc --die-with-parent", "--ro / --rw /dev/null", "(version 1) (allow default) (deny file-write*)"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "@pentest-harness/"
            or (ProcessCommandLine has "tsx/esm" and ProcessCommandLine has "apps/cli/src/bin.ts")
            or (ProcessCommandLine has_any ("apps/cli/lib/bin.js", "apps/cli/lib/index.js") and ProcessCommandLine has " web")
            or (ProcessCommandLine has_any (Wrappers) and ProcessCommandLine has " -c " and InitiatingProcessFileName in~ ("node", "node.exe"))
        | summarize Events=count(), Commands=make_set(substring(ProcessCommandLine, 0, 250), 20), Timestamp=min(Timestamp)
            by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="Pentest Harness (or dsh family) launch or sandboxed agent shell", Detail=tostring(Commands), Parent),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 2323
        | where InitiatingProcessFileName in~ ("node", "node.exe")
        | project Timestamp, DeviceName, Signal="node listening on 2323, the Pentest Harness web UI port (check for ~/.dsh)", Detail=strcat(LocalIP, ":", LocalPort), Parent=InitiatingProcessCommandLine),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath has "/.dsh/" or FolderPath has @"\.dsh\")
            and (FileName in~ (".credentials.yaml", ".anonymous-user-id", "settings.yaml", "session.jsonl", "session.jsonl.zstd"))
            or FolderPath has "@pentest-harness/node-addon-landlock-run-"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, Parent=InitiatingProcessCommandLine
        | project Timestamp, DeviceName, Signal="Pentest Harness (or dsh family) home folder or launcher files", Detail=tostring(Files), Parent)
| order by Timestamp desc

// Pentest Harness user agents, web UI use and opt-in telemetry in web and proxy logs
// Agentic attack detections by ThreatDefence (Pentest Harness). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1595 (Active Scanning)
// From the Pentest Harness source code (S1N6H/pentest-harness, reviewed at 4638f38):
//  - Every model request carries "pentest-harness/<version> (+https://github.com/S1N6H/pentest-harness)" (0.1.1-rc.2 at
//    this commit); a proxy that inspects TLS sees it on api.deepseek.com or whichever provider is configured. Its web
//    fetch, off by default, sends "pentest-harness/0.0.1 (+https://github.com/S1N6H/pentest-harness)" to the pages it reads.
//  - Its DeepSeek web search sends "deepseek-harness/0.0.1" (dsh family); opt-in telemetry goes to
//    harness-telemetry.deepseeksvc.com (dsh family).
//  - A browser using the web UI loads /plugins/@pentest-harness/dsh-client-<name>/client.js?rev=..., and the UI calls
//    POST /api/session.prompt, /api/credentials.set and other /api/<method> routes. A /api call that reaches a web
//    server log with Host 127.0.0.1 or localhost from a remote address is someone using an exposed harness.

let Window = 30d;
let Ua = "(+https://github.com/S1N6H/pentest-harness)";
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestClientApplication has Ua or RequestClientApplication startswith "deepseek-harness/"
            or RequestURL has "/plugins/@pentest-harness/dsh-client-" or DestinationHostName =~ "harness-telemetry.deepseeksvc.com"
        | project TimeGenerated, Src=SourceIP, Target=DestinationHostName,
            Signal=case(RequestClientApplication has Ua, "Pentest Harness user agent (model request or web fetch)",
                        RequestClientApplication startswith "deepseek-harness/", "dsh family web search user agent",
                        RequestURL has "/plugins/@pentest-harness/", "Pentest Harness web UI loaded through the proxy",
                        "dsh family opt-in telemetry"),
            Detail=strcat(RequestURL, " ", RequestClientApplication)),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where csUserAgent has "S1N6H/pentest-harness"
        | summarize Requests=count(), Paths=make_set(csUriStem, 20), Start=min(TimeGenerated) by cIP, csHost, csUserAgent
        | project TimeGenerated=Start, Src=cIP, Target=csHost, Signal="Pentest Harness web fetch reached this site", Detail=strcat(csUserAgent, " ", tostring(Paths)))
| order by TimeGenerated desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Pentest Harness). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1071.001 (Application Layer Protocol: Web Protocols)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.
// No Pentest Harness infrastructure has been published, so these rows are fingerprints of the software: its user
// agents, console strings, file names and the hosts its default configuration uses.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "pentest-harness" | project value=tostring(SearchKey), type, confidence, actor, source;
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Agents = toscalar(IOC | where type == "user_agent" | summarize make_list(value));
let Names = toscalar(IOC | where type in ("file_name", "file_path") or (type == "string" and confidence == "high") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where DestinationHostName has_any (Domains) or RequestClientApplication in (Agents) or RequestURL has_any (Names)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=iff(RequestClientApplication in (Agents), RequestClientApplication, DestinationHostName), Detail=strcat(SourceIP, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUserAgent in (Agents)
        | project TimeGenerated, Source="W3CIISLog", Indicator=csUserAgent, Detail=strcat(cIP, " ", csUriStem)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteUrl, Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Names)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Names)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=DeviceName),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator
| order by LastSeen desc

// PentestAgent (nbshenxm paper code) running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestAgent, nbshenxm/pentest-agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1588.005 (Obtain Capabilities: Exploits)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the source code (nbshenxm/pentest-agent at 97ac5be7), the research code of arXiv 2411.05185. Not the
// GH05TCREW/pentestagent tool, which has its own folder.
//  - The operator runs python agents/recon_agent.py, agents/planning_agent.py and agents/execution_agent.py.
//    The recon and execution agents run every command the model returns with /bin/sh -c (nmap, curl, the exploit).
//  - The planning agent runs cvemap -q <product> -l 50 -offset <n> -j, echo CVE-<id> | cvemap -json > .../info/cvemap.json
//    and searchsploit CVE-<id> -j > resources/CVE-<id>/exploitdb.json, and clones public exploit repositories.
//  - Files: exeuction_agent.log (misspelled), recon_memory/<topic>.json, <keyword>/CVEMAP/cvemap.json, plan.json,
//    <CVE>/Trend_Score.json and conf_score_from_code_<repo>.json.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any ("agents/recon_agent.py", "agents/planning_agent.py", "agents/execution_agent.py")
            or (ProcessCommandLine has "cvemap" and ProcessCommandLine has " -offset " and ProcessCommandLine has " -l 50 ")
            or (ProcessCommandLine has "| cvemap -json > " and ProcessCommandLine has "/info/cvemap.json")
            or (ProcessCommandLine has "searchsploit " and ProcessCommandLine has " -j > resources/")
        | project Timestamp, DeviceName, Signal="PentestAgent script, cvemap or searchsploit", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessCommandLine has_any ("agents/recon_agent.py", "agents/execution_agent.py")
            and FileName in~ ("sh", "dash", "bash")
        | project Timestamp, DeviceName, Signal="Command run by a PentestAgent agent", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=substring(InitiatingProcessCommandLine, 0, 150)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName == "exeuction_agent.log" or FileName == "Trend_Score.json"
            or FolderPath has "/CVEMAP/" or FileName startswith "conf_score_from_code_" or FileName startswith "otpt_from_code_"
            or FolderPath has "/recon_memory/"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, FolderPath
        | project Timestamp, DeviceName, Signal="PentestAgent log, memory or planning file", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// PentestAgent (nbshenxm paper code) testing you: its default proof command in web and proxy logs
// Agentic attack detections by ThreatDefence (PentestAgent, nbshenxm/pentest-agent). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1190 (Exploit Public-Facing Application), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the source code (nbshenxm/pentest-agent at 97ac5be7). The execution agent is told to prove code execution with
// command_to_execute, default "touch /tmp/success" (configs/config.yaml:129), so the command lands in whatever exploit
// request the model builds. The agent adds no user agent or marker of its own; before the exploit the same source
// usually runs nmap with http-enum, http-title, http-server-header and http-headers (Nmap Scripting Engine user agent).
// Vulhub uses the same proof command in its examples, so a match is an attempt to prove code execution, by this agent
// or by someone following Vulhub. Not the GH05TCREW/pentestagent tool, which has its own folder.

let Marker = @"touch(\s|\+|%20|\$\{IFS\})+(/|%2[fF])tmp(/|%2[fF])success";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriQuery matches regex Marker or csUriStem matches regex Marker
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Marker
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (AzureDiagnostics | where Category in ("ApplicationGatewayFirewallLog", "FrontDoorWebApplicationFirewallLog")
        | where requestUri_s matches regex Marker or details_data_s matches regex Marker
        | project TimeGenerated, Source="WAF", Src=clientIp_s, Target=hostname_s, Detail=strcat(requestUri_s, " ", details_data_s), UA="")
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// PentestCode running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestCode). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// PentestCode (s0ld13rr/pentestcode) is a hard fork of the OpenCode coding agent turned into a 13-agent penetration
// tester for internal networks and Active Directory. No report of its use in a real intrusion was found on
// November 26, 2026, so this hunt looks for the software itself, from its source code (reviewed at b7db9ccb):
//  - One binary, pentestcode (Bun single-file executable, installed to ~/.local/bin by install.sh, npm package
//    pentestcode-ai, AUR pentestcode-bin, brew tap s0ld13rr/tap). Every agent command is <shell> -c <command> with
//    pentestcode as the parent. Tool calls need no approval: the default permission is "*": "allow".
//  - Its ensure_tools tool runs which <tool> for nmap, nuclei, netexec, certipy, bloodhound-python, impacket-smbclient,
//    ligolo-proxy and others, and the fixed check
//    bash -c "ls /usr/share/seclists 2>/dev/null || ls /opt/seclists 2>/dev/null || ls ~/seclists 2>/dev/null".
//  - Its tunnel_manage tool writes /tmp/pc.conf and runs proxychains4 -q -f /tmp/pc.conf nmap -sT -Pn -n -p 22,80,445.
//  - Its screenshot tool runs chromium --headless --disable-gpu --no-sandbox --screenshot=/tmp/screenshot-<ms>.png.
//  - Files: ~/.pentestcode/engagements/<name>/state.json and findings.md, ~/.pentestcode/knowledge/global.json,
//    ~/.pentestcode/skills/bundled/, ~/.local/share/pentestcode/pentestcode.db, ~/.config/pentestcode/.
// The binary name and the paths need a code change to remove; the shell form is stock OpenCode.

let Window = 30d;
let PcProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("pentestcode", "pentestcode.exe") or InitiatingProcessFileName in~ ("pentestcode", "pentestcode.exe")
        or ProcessCommandLine contains "ls /usr/share/seclists 2>/dev/null || ls /opt/seclists"
        or ProcessCommandLine contains "-f /tmp/pc.conf"
        or (ProcessCommandLine contains "--screenshot=/tmp/screenshot-" and ProcessCommandLine contains "--no-sandbox")
        or ProcessCommandLine has_any ("pentestcode-ai", "pentestcode-bin", "s0ld13rr/pentestcode", "s0ld13rr/tap");
union isfuzzy=true
    (PcProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 15), Timestamp=min(Timestamp) by DeviceName, AccountName
        | project Timestamp, DeviceName, AccountName, Signal="PentestCode binary, its agent shells or its fixed tool commands", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"/\.pentestcode/(engagements|knowledge|skills/bundled)/|/\.local/share/pentestcode/"
        | summarize Files=make_set(FileName, 15), Timestamp=min(Timestamp) by DeviceName, AccountName=InitiatingProcessAccountName
        | project Timestamp, DeviceName, AccountName, Signal="PentestCode engagement or data folder", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessFileName in~ ("pentestcode", "pentestcode.exe")
        | where ActionType == "ListeningConnectionCreated" or LocalPort == 4096
        | summarize Remotes=make_set(RemoteIP, 10), Timestamp=min(Timestamp) by DeviceName, AccountName=InitiatingProcessAccountName
        | project Timestamp, DeviceName, AccountName, Signal="PentestCode server listening or serving (4096 by default)", Detail=tostring(Remotes))
| order by Timestamp desc

// PentestCode testing you: inject_probe markers and its user agents in web and proxy logs
// Agentic attack detections by ThreatDefence (PentestCode). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the PentestCode source code (s0ld13rr/pentestcode, reviewed at b7db9ccb):
//  - Its inject_probe tool sends up to 120 fixed payloads per call into query, form, JSON and cookie parameters, with a
//    browser user agent (Chrome 143 on Windows). Three of them carry markers set in the code: the tag <pctsttag> (XSS),
//    echo pctstcmd after ; | $( & || (command injection) and template expressions built on 7919*6841 (SSTI, it looks
//    for 54173879 in the answer). The other payloads are generic: ;id, ' OR '1'='1, ../../../etc/passwd,
//    http://169.254.169.254/latest/meta-data/ and the like, sent next to the marked ones.
//  - Its page fetcher retries with the user agent pentestcode after a Cloudflare challenge; its model, catalog and search
//    clients send pentestcode/<channel>/<version>/<client> or pentestcode/<version>.
// A marker means the agent was probing that endpoint: look at the generic payloads from the same source around it.

let Markers = @"pctst(tag|cmd)|7919\*6841";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriQuery matches regex Markers or csCookie matches regex Markers or UA startswith "pentestcode"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Markers or RequestClientApplication startswith "pentestcode"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// PentestCode working on a host it compromised: pivot staging, tunnel agents and os_hook command templates
// Agentic attack detections by ThreatDefence (PentestCode). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1105 (Ingress Tool Transfer), T1572 (Protocol Tunneling), T1053.005 (Scheduled Task/Job: Scheduled Task), T1547.001 (Boot or Logon Autostart Execution: Registry Run Keys / Startup Folder)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the PentestCode source code (s0ld13rr/pentestcode, reviewed at b7db9ccb). These commands run on YOUR hosts after
// PentestCode has a shell there; the agent writes them from recipes its tools return, so they are likely, not certain:
//  - tunnel_manage (packages/opencode/src/tool/tunnel-manage.ts): a chisel or ligolo-ng binary pushed through the RCE as
//    2 KB base64 chunks appended to /tmp/<name>.b64, then base64 -d /tmp/<name>.b64 > /tmp/<name> && chmod +x /tmp/<name>
//    && /tmp/<name> --version, then /tmp/<name> client <attacker>:8000 R:<port>:socks (chisel) or
//    /tmp/<name> -connect <attacker>:11601 -ignore-cert (ligolo-ng agent).
//  - os_hook (packages/opencode/src/tool/os-hook.ts) on Windows: schtasks /create /tn "UpdateCheck" ... /sc onlogon
//    /ru SYSTEM, reg add ...\CurrentVersion\Run /v Update /t REG_SZ, netsh advfirewall firewall add rule name="Allow",
//    nslookup -type=any _ldap._tcp.dc._msdcs.%USERDNSDOMAIN%, and netexec --sam, --lsa, bare --dpapi and --ntds dumps.
//  - Its identity agent's Active Directory order: GetNPUsers.py -no-pass -usersfile, GetUserSPNs.py -request,
//    bloodhound-python -c All, certipy find/req, netexec smb --rid-brute, --gen-relay-list, -M gpp_password, -M laps.
//    These are standard tool lines shared with every operator; the behaviors/ hunts cover them in general.

let Window = 30d;
DeviceProcessEvents
| where Timestamp > ago(Window)
| extend Signal = case(
    ProcessCommandLine contains "base64 -d /tmp/" and ProcessCommandLine contains ".b64 > /tmp/" and ProcessCommandLine contains "chmod +x /tmp/", "Pivot binary decoded from /tmp/*.b64 and made executable",
    ProcessCommandLine contains "/tmp/" and ProcessCommandLine contains " client " and ProcessCommandLine contains ":8000 R:" and ProcessCommandLine contains ":socks", "chisel reverse SOCKS client started from /tmp",
    ProcessCommandLine contains "/tmp/" and ProcessCommandLine contains " -connect " and ProcessCommandLine contains ":11601" and ProcessCommandLine contains "-ignore-cert", "ligolo-ng agent started from /tmp",
    ProcessCommandLine contains "/tn \"UpdateCheck\"" and ProcessCommandLine contains "/sc onlogon" and ProcessCommandLine contains "/ru SYSTEM", "os_hook scheduled task UpdateCheck",
    ProcessCommandLine contains @"\CurrentVersion\Run" and ProcessCommandLine contains "/v Update " and ProcessCommandLine contains "REG_SZ", "os_hook Run key value Update",
    ProcessCommandLine contains "advfirewall firewall add rule" and ProcessCommandLine contains "name=\"Allow\"", "os_hook firewall rule Allow",
    ProcessCommandLine contains "_ldap._tcp.dc._msdcs.%USERDNSDOMAIN%", "os_hook domain controller lookup",
    "")
| where isnotempty(Signal)
| project Timestamp, DeviceName, AccountName, Signal, Detail=substring(ProcessCommandLine, 0, 300),
    Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))
| order by Timestamp desc

// PentestGPT running on a host you monitor
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the PentestGPT source code (GreyDGL/PentestGPT at e8b1bb77, main, and 83ae3647, v1.0.0):
//  - Main: pentestgpt-agent --goal <text> --target <target> [--backend claude|codex]. It starts the Claude Code CLI
//    with --permission-mode bypassPermissions and --append-system-prompt "You are the Supervisor for an authorized
//    penetration test. ..." or "You are the Executor for an authorized penetration test. ...". Codex gets the same
//    instructions over its app-server protocol, so they are not on its command line.
//  - Main writes runs/<run>/trial-config.json, state.sqlite3, summary.json and traces/supervisor-r<n>/ and
//    traces/executor-<id>/ (input.json, events.jsonl, output.json); the model sessions work in
//    agent-workspaces/<run>/supervisor and executor.
//  - v1.0.0: pentestgpt --target <target>, Claude Code with --system-prompt "You are PentestGPT, an AI-powered CTF
//    challenge solver ...", files ~/.pentestgpt/user_id, ~/.pentestgpt/sessions/<id>.json, pentestgpt-debug.log, and
//    Langfuse telemetry to us.cloud.langfuse.com unless --no-telemetry or LANGFUSE_ENABLED=false.
//  - Legacy (the paper's interactive version): pentestgpt-legacy, logs/pentestGPT.log, logs/pentestGPT_log_<time>.txt.
// The prompt strings need a code change to remove. File locations follow --runs-root, --workspace-root and --log-dir.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine contains "You are the Supervisor for an authorized penetration test."
            or ProcessCommandLine contains "You are the Executor for an authorized penetration test."
            or ProcessCommandLine contains "You are PentestGPT, an AI-powered CTF challenge solver"
        | project Timestamp, DeviceName, Signal="Model CLI started with a PentestGPT prompt",
            Detail=substring(ProcessCommandLine, 0, 300), Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt-agent(-audit)?(\.exe)?[""']?\s(.*\s)?--(goal|target|run-dir|expected-flag|resume|backend)[\s=]"
            or ProcessCommandLine contains "-m pentestgpt_agent.trial" or ProcessCommandLine contains "-m pentestgpt_agent.audit"
            or ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt(\.exe)?[""']?\s(.*\s)?(--target|-t|--non-interactive|--no-telemetry|--list-sessions|--session-id)[\s=]"
            or ProcessCommandLine matches regex @"(^|[/\\\s""'])pentestgpt-(benchmark|legacy|legacy-connection)(\.exe)?([""']|\s|$)"
        | project Timestamp, DeviceName, Signal="PentestGPT command", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.pentestgpt[/\\](sessions[/\\]|user_id$)"
            or FileName in~ ("pentestgpt-debug.log", "pentestGPT.log") or FileName startswith "pentestGPT_log_"
            or FolderPath matches regex @"[/\\]traces[/\\](supervisor-r\d+(-a\d+)?|executor-[0-9a-f]{32})[/\\](input|output)\.json$"
            or FileName =~ "trial-config.json"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="PentestGPT run, session or log files", Detail=tostring(Files), Parent=InitiatingProcessFileName),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "us.cloud.langfuse.com" and InitiatingProcessCommandLine has "pentestgpt"
        | project Timestamp, DeviceName, Signal="PentestGPT v1.0.0 telemetry", Detail=RemoteUrl, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1059.006 (Command and Scripting Interpreter: Python)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. PentestGPT has no addresses or C2 of its own: its rows are the v1.0.0 telemetry
// host (shared with every Langfuse user, so a lead only), file names and paths, and prompt strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "pentestgpt" | project value=tostring(SearchKey), type, confidence, actor, source;
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Files = toscalar(IOC | where type == "file_name" | summarize make_list(value));
let Paths = toscalar(IOC | where type == "file_path" | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence == "high" | summarize make_list(value));
union isfuzzy=true
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteUrl,
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=DestinationHostName, Detail=strcat(SourceIP, " ", RequestURL)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Files) or FolderPath has_any (Paths)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator="PentestGPT string in command line",
            Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200)))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// PentestGPT telemetry and the UnifiedAgent Inspector in network and proxy logs
// Agentic attack detections by ThreatDefence (PentestGPT). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the PentestGPT source code (GreyDGL/PentestGPT at 83ae3647, v1.0.0, and e8b1bb77, main):
//  - PentestGPT does not mark its traffic to targets: no user agent, canary, callback domain or path list. Its target
//    side looks like curl, nmap and whatever else the model runs, which the behaviors/ hunts cover.
//  - v1.0.0 sends Langfuse telemetry by default: POST https://us.cloud.langfuse.com/api/public/otel/v1/traces with the
//    header x_langfuse_public_key: pk-lf-49d66e88-3a92-478e-92a6-09bae920d69a. It carries the target, the agent's
//    messages, each tool call's arguments and each flag found. Many LLM applications use the same Langfuse host, so a
//    host match is a lead; the key, where a TLS-inspecting proxy logs request headers, is not.
//  - The unified-agent dependency can serve a run viewer, "UnifiedAgent Inspector", on 127.0.0.1:8765 with /api/runs,
//    /api/runs/<id>/events and /api/runs/<id>/stream. It refuses non-loopback addresses, so seeing it through a proxy
//    or a load balancer means someone published it on purpose. Run ids from PentestGPT look like
//    trial-<12 hex>--supervisor-r<n> or trial-<12 hex>--executor-<id>.

let Window = 30d;
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where DestinationHostName =~ "us.cloud.langfuse.com" or RequestURL has "us.cloud.langfuse.com/api/public/otel"
        | extend Key=extract(@"pk-lf-[0-9a-f-]{36}", 0, AdditionalExtensions)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP,
            Signal=iff(Key == "pk-lf-49d66e88-3a92-478e-92a6-09bae920d69a", "PentestGPT v1.0.0 telemetry key", "Langfuse US cloud (lead)"),
            Detail=strcat(RequestURL, " ", Key)),
    (DeviceNetworkEvents | where Timestamp > ago(Window)
        | where RemoteUrl has "us.cloud.langfuse.com"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=DeviceName,
            Signal=iff(InitiatingProcessCommandLine has "pentestgpt", "PentestGPT v1.0.0 telemetry", "Langfuse US cloud (lead)"),
            Detail=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 200))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestURL matches regex @"/api/runs/trial-[0-9a-f]{12}--(supervisor-r\d+|executor-)"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Signal="UnifiedAgent Inspector showing PentestGPT runs",
            Detail=strcat(DestinationHostName, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where csUriStem matches regex @"^/api/runs/trial-[0-9a-f]{12}--(supervisor-r\d+|executor-)"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Signal="UnifiedAgent Inspector showing PentestGPT runs",
            Detail=strcat(csHost, " ", csUriStem))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Src, Signal
| order by Signal asc, LastSeen desc

// Pentest Swarm AI on a host you monitor
// Agentic attack detections by ThreatDefence (Pentest Swarm AI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Pentest Swarm AI (Armur-Ai/Pentest-Swarm-AI, binary pentestswarm) runs recon, exploit and report agents against a
// target. No report of its use in a real intrusion was found on November 23, 2026, so this hunt looks for the
// software itself, from its source code:
//  - The binary pentestswarm (scan, serve, lab) or the image ghcr.io/armur-ai/pentestswarm.
//  - The consent switches PENTESTSWARM_AUTHORIZED=1 and --authorized, which skip the typed "I AGREE".
//  - ~/.pentestswarm/authorization.json and authorization.log: the log has one JSON line per real target.
//  - The tools it starts: nmap -sV -T4 -Pn --top-ports 1000 -oX -, nuclei -jsonl -silent, ffuf, dalfox, and
//    interactsh-client -json -poll-interval 1 for callbacks.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Tools = dynamic(["nmap", "nuclei", "ffuf", "dalfox", "sqlmap", "httpx", "subfinder", "katana", "naabu", "interactsh-client"]);
let SwarmProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ ("pentestswarm", "pentestswarm.exe")
        or ProcessCommandLine has_any ("armur-ai/pentestswarm", "PENTESTSWARM_AUTHORIZED", "pentestswarm-lab-");
let SwarmDevices = SwarmProcesses | distinct DeviceName;
union isfuzzy=true
    (SwarmProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName, AccountName
        | project Timestamp, DeviceName, Signal="Pentest Swarm AI binary or image", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (SwarmDevices)
        | where InitiatingProcessFileName in~ ("pentestswarm", "pentestswarm.exe") and tolower(FileName) in (Tools)
        | summarize Started=make_set(FileName, 20), Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Security tools started by Pentest Swarm AI", Detail=strcat(tostring(Started), " ", tostring(Commands))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.pentestswarm/" or FolderPath has @"\.pentestswarm\"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Pentest Swarm AI consent file or target log", Detail=tostring(Files))
| order by Timestamp desc

// Pentest Swarm AI testing you: its negative-control probe and verification markers in web and proxy logs
// Agentic attack detections by ThreatDefence (Pentest Swarm AI). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Pentest Swarm AI source code (Armur-Ai/Pentest-Swarm-AI, reviewed at 1f7c3902):
//  - API discovery starts with GET /nx-<16 hex> and GET /api/nx-<16 hex> to learn what a missing path looks like.
//  - With verification on it sends https://evil.pentestswarm.invalid/pstest in redirect parameters and the template
//    check 191*193 (expecting 36863).
//  - Toward targets it sends a Chrome 141 user agent on macOS, so there is no user agent to match. Its own user
//    agents (pentestswarm-cli, pentestswarm-npm, pentestswarm-webhook/1.0) go to GitHub, npm and webhooks.
// The negative-control path alone is a weak signal; the Paths column shows what the same source asked for next.

let Control = @"^/(api/)?nx-[0-9a-f]{16}$";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriStem matches regex Control or csUriQuery contains "evil.pentestswarm.invalid" or csUriQuery contains "191*193" or csUriQuery contains "191%2A193" or UA startswith "pentestswarm-"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL contains "evil.pentestswarm.invalid" or RequestURL contains "191*193" or RequestURL contains "191%2A193" or RequestURL matches regex @"/(api/)?nx-[0-9a-f]{16}$" or RequestClientApplication startswith "pentestswarm-"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Paths=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// RAPTOR running on a host you monitor
// Agentic attack detections by ThreatDefence (RAPTOR). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.006 (Command and Scripting Interpreter: Python), T1588.002 (Obtain Capabilities: Tool), T1587.004 (Develop Capabilities: Exploits)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the RAPTOR source code (gadievron/raptor at ac734352). RAPTOR is a security research framework that runs as a
// Claude Code session from a git checkout (or the docker.io/danielcuthbert/raptor tools image):
//  - Launcher bin/raptor ends in: claude --plugin-dir <raptor>/plugins/coverage -n RAPTOR /raptor
//    after python3 -I <raptor>/core/security/scratch_supervisor.py ... --_scratch-session-stage
//  - Claude Code hooks and slash commands run libexec/raptor-* helpers (raptor-session-init, raptor-lifecycle-hook,
//    raptor-agentic, raptor-run-sandboxed, ...); pipelines run python3 <raptor>/raptor.py agentic|web|scan|fuzz|codeql
//  - Files: <raptor>/out/<command>_<target>_<YYYYMMDD_HHMMSS>_pid<N>_<seq>/.raptor-run.json, autonomous/exploits/<id>_exploit.cpp,
//    autonomous/patches/<id>_patch.md, <raptor>/.claude/raptor.env, ~/.config/raptor/models.json, ~/.raptor/projects/,
//    ~/.local/share/raptor/sessions.d/<pid>

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine has "plugins/coverage" and ProcessCommandLine has "-n RAPTOR")
            or ProcessCommandLine has_any ("/core/security/scratch_supervisor.py", "/core/startup/install_guard.py", "--_scratch-session-stage")
            or ProcessCommandLine contains "libexec/raptor-"
            or ProcessCommandLine has_any ("raptor.py agentic", "raptor.py web --url", "raptor.py scan --repo", "raptor.py codeql --repo",
                "raptor.py fuzz --binary", "raptor_agentic.py", "raptor_fuzzing.py", "raptor_codeql.py", "packages/web/scanner.py")
        | project Timestamp, DeviceName, AccountName, Signal="RAPTOR process", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName == ".raptor-run.json"
            or FolderPath endswith "/.claude/raptor.env" or FolderPath endswith "/.config/raptor/models.json"
            or FolderPath contains "/.raptor/projects/" or FolderPath contains "/.local/share/raptor/sessions.d/"
            or (FolderPath contains "/autonomous/exploits/" and FileName matches regex @"_exploit\.(cpp|c|py|java|js|go|rb)$")
            or (FolderPath contains "/autonomous/patches/" and FileName endswith "_patch.md")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, AccountName=InitiatingProcessAccountName, FolderPath
        | project Timestamp, DeviceName, AccountName, Signal="RAPTOR files", Detail=strcat(FolderPath, " ", tostring(Files)), Parent="")
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (RAPTOR). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. RAPTOR has no infrastructure of its own, so its rows are user agents, probe
// strings, URI strings, file names and paths; the sweep looks for the user agents in web and proxy logs, the URI
// strings in web logs, and the strings and paths on hosts.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "raptor" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Uris = toscalar(IOC | where type == "uri_string" and confidence in ("high", "medium") | summarize make_list(value));
let Strings = toscalar(IOC | where type in ("string", "file_name", "file_path") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL has_any (Uris)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=RequestClientApplication, Detail=strcat(SourceIP, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has_any (UAs) or csUriStem has_any (Uris) or csUriQuery has_any (Uris)
        | project TimeGenerated, Source="W3CIISLog", Indicator=UA, Detail=strcat(cIP, " ", csUriStem, "?", csUriQuery)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=strcat(DeviceName, " ", FolderPath))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator
| order by LastSeen desc

// RAPTOR web scanner in web and proxy logs: its user agent, probe paths and probe values, and its client user agents
// Agentic attack detections by ThreatDefence (RAPTOR). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1595.003 (Active Scanning: Wordlist Scanning), T1110.001 (Brute Force: Password Guessing)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the RAPTOR source code (gadievron/raptor, reviewed at ac734352), packages/web:
//  - Every request from its HTTP client: User-Agent "RAPTOR Security Scanner (Authorized Testing)" (client.py:199).
//    The Playwright browser it uses for crawling and the XSS proof does not set it, nor does ffuf or nuclei.
//  - Fixed probes: /this-path-does-not-exist-raptor-probe, /api/does-not-exist-raptor, /raptor-<16 hex>-does-not-exist,
//    /raptor-<16 hex>/nonexistent.css, raptornosuchparam=raptorparam1, ?raptorcb=<12 hex>, window.__raptor_hits,
//    raptor_pp_probe_value_8472, evil-raptor-probe.example.com, state=raptor_probe, raptor-baseline, raptor@example.invalid
//  - Login checks post username raptor_nonexistent_user_xyzzy_9291 and passwords raptor_probe_password_<0-4> and
//    raptor_final_probe; those sit in request bodies, which web logs rarely keep.
//  - From the operator's host: raptor/0.1 (+https://github.com/gadievron/raptor), raptor-sca/0.1 (...), raptor-nvd/0.1,
//    raptor-sca and the other raptor-* clients, to package registries, GitHub, OSV and NVD.

let ScannerUA = "RAPTOR Security Scanner";
let UriMarkers = dynamic(["does-not-exist-raptor", "/raptor-clzero-probe", "raptornosuchparam=", "raptorcb=", "__raptor_hits",
    "raptor_pp_probe_value_8472", "evil-raptor-probe.example.com", "state=raptor_probe", "=raptor-baseline", "raptor%40example.invalid"]);
let ClientUA = @"^(raptor(-sca)?/[0-9.]+ \(\+https://github\.com/gadievron/raptor\)|raptor-sca|raptor-(nvd|env-verify|container-evidence|uv-provenance|cvefix-envs)/[0-9.]+)$";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " "), Url=strcat(csUriStem, "?", csUriQuery)
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csMethod, " ", Url), UA, Url),
    (CommonSecurityLog | where isnotempty(RequestURL) or isnotempty(RequestClientApplication)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication, Url=RequestURL)
| where TimeGenerated > ago(90d)
| extend Signal=case(UA startswith ScannerUA, "RAPTOR web scanner user agent",
    Url has_any (UriMarkers) or Url matches regex @"/raptor-[0-9a-f]{16}(-does-not-exist|/nonexistent\.css)", "RAPTOR web scanner probe",
    UA matches regex ClientUA, "RAPTOR client user agent",
    "")
| where isnotempty(Signal)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Signal, Source, Src, Target
| order by FirstSeen asc

// RedAmon on a host you monitor, and the reverse shell tunnel it opens
// Agentic attack detections by ThreatDefence (RedAmon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1572 (Protocol Tunneling)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// RedAmon (samugit83/redamon) is a self-hosted penetration testing platform. No report of its use in a real intrusion
// was found on November 23, 2026, so this hunt looks for the software itself, from its source code:
//  - The Docker Compose stack: containers redamon-webapp, redamon-agent, redamon-kali, redamon-recon-<id>,
//    redamon-docker-broker, the control script redamon.sh, and the sandbox servers under /opt/mcp_servers.
//  - Per-scan tool containers (redamon-httpx-<id>, redamon-nuclei-detection-<id>) and the scratch folder /tmp/redamon.
//  - Reverse shells: a Metasploit handler on port 4444 in the sandbox, reached through ngrok tcp 4444 or
//    chisel client <url> R:4444:localhost:4444, and interactsh-client -server oast.fun for callbacks.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Stack = dynamic(["redamon-kali", "redamon-agent", "redamon-webapp", "redamon-recon-", "redamon-docker-broker", "redamon-httpx-",
    "redamon-nuclei-", "/opt/mcp_servers/run_servers.py", "/opt/mcp_servers/tunnel_manager.py", "redamon.sh "]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Stack)
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="RedAmon stack or sandbox process", Detail=tostring(Commands)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "ngrok tcp 4444"
            or (ProcessCommandLine has "chisel client" and ProcessCommandLine has "R:4444:localhost:4444")
            or (ProcessCommandLine has "interactsh-client" and ProcessCommandLine has "oast.fun")
        | project Timestamp, DeviceName, Signal="Reverse shell tunnel or callback client the RedAmon sandbox starts", Detail=substring(ProcessCommandLine, 0, 300)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath startswith "/tmp/redamon/" or FileName =~ "redamon.sh" or FolderPath has "/.redamon-deploy/"
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="RedAmon files", Detail=tostring(Files))
| order by Timestamp desc

// RedAmon scanning you: its user agents, canaries and ownership lookup in web, proxy and DNS logs
// Agentic attack detections by ThreatDefence (RedAmon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the RedAmon source code (samugit83/redamon, reviewed at 73ca9d38):
//  - User agents that name it: RedAmon-AISurfaceRecon/1.0 (on by default, probes model API and MCP paths),
//    "Mozilla/5.0 (compatible; RedAmon/4.7)", RedAmon-JsRecon/1.0 and RedAmon-CachePoison/1.0 (modules off by default).
//  - The XSS canary rEdAm0n1337XsS, which the agent's prompt says to put in every parameter, in User-Agent and in Referer.
//  - The cache buster rdmncb=cb<12 hex> of its cache poisoning tests.
//  - A TXT lookup for _redamon-verify.<domain>, when a project turns on ownership verification.
// These are code defaults. Penetration testers run RedAmon too, so check whether the test was agreed.

let Canaries = @"rEdAm0n1337XsS|rdmncb=cb";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where UA has "RedAmon" or csUriQuery matches regex Canaries or csReferer contains "rEdAm0n1337XsS"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestClientApplication has "RedAmon" or RequestURL matches regex Canaries
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication),
    (DnsEvents | where Name startswith "_redamon-verify."
        | project TimeGenerated, Source="DnsEvents", Src=ClientIP, Target=Name, Detail="ownership check lookup", UA="")
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// Sage (Mythic AI operator) on a server you monitor
// Agentic attack detections by ThreatDefence (Sage (Mythic)). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.007 (Obtain Capabilities: Artificial Intelligence), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Sage (MythicAgents/sage, reviewed at cbff42f0) installs into a Mythic C2 server as the chat container "sage". From its source:
//  - python3 /usr/local/bin/sage-entrypoint, then python3 main.py in /Mythic; the BloodHound MCP server runs as
//    uv --directory /opt/bloodhound_mcp run --no-sync main.py.
//  - It embeds Arize Phoenix: a listener on 6006 (UI and API, no login by default) and 4317 (OTLP gRPC), bound to every
//    interface of the container by Phoenix's default.
//  - Files in <Mythic>/InstalledServices/sage/: sage.db, .phoenix/phoenix.db, .sage_engagement/, tools/.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let SageProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where ProcessCommandLine has "/usr/local/bin/sage-entrypoint"
        or (ProcessCommandLine has "--directory /opt/bloodhound_mcp" and ProcessCommandLine has "main.py");
let SageDevices = SageProcesses | distinct DeviceName;
union isfuzzy=true
    (SageProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Sage entrypoint or its BloodHound MCP server", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath has "/InstalledServices/sage/" and (FileName =~ "sage.db" or FolderPath has "/.phoenix/phoenix.db"))
            or FolderPath has "/.sage_engagement/"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Sage state or Phoenix trace database", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (SageDevices)
        | where (ActionType == "ListeningConnectionCreated" and LocalPort in (6006, 4317))
            or (ActionType == "InboundConnectionAccepted" and LocalPort == 6006 and RemoteIPType == "Public")
        | summarize Remotes=make_set(RemoteIP, 20), Timestamp=min(Timestamp) by DeviceName, ActionType, LocalPort
        | project Timestamp, DeviceName, Signal=strcat("Phoenix port ", tostring(LocalPort), ": ", ActionType), Detail=tostring(Remotes))
| order by Timestamp desc

// Commands and files from Sage tasks on Windows hosts
// Agentic attack detections by ThreatDefence (Sage (Mythic)). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1047 (Windows Management Instrumentation), T1053.005 (Scheduled Task), T1059.001 (PowerShell), T1649 (Steal or Forge Authentication Certificates), T1685 (Disable or Modify Tools)
// Example hunt for Microsoft Sentinel with Defender XDR tables. Test and baseline before alerting.
// Sage proposes Mythic tasks that a payload callback (Apollo) runs. Its defaults leave these on the hosts it works on:
//  - cmd.exe /c echo SAGE_REMOTE_EXEC_PROOF_<host>_<callback> & whoami & hostname & echo ... > C:\Windows\Temp\sage_remote_exec_<host>_<callback>.txt
//  - schtasks.exe /Create /S <host> /RU SYSTEM /SC ONCE /ST 23:59 /TN "SageExec_<suffix>" ...; event 4698 for SageExec_
//  - certutil.exe -f -p SagePfx-v1-<...> -backupKey C:\Windows\Temp\sage_ca_export_<slug>_backup; certreq in %TEMP%\sage_cert_enroll_<slug>
//  - PowerShell with SAGE_*_PROOF markers, New-PSDrive -Name SAGEPROOF/SAGEEP/SAGECA, CERT_AUTH_METHOD=schannel-ldap,
//    and Set-MpPreference -DisableRealtimeMonitoring with Add-MpPreference -ExclusionPath C:\Windows\Temp
//  - C:\Users\Public\sage_gpo_<slug>_whoami.txt from a Group Policy immediate task
// A different marker, path or task name passed by the operator or the model replaces these defaults.

let Window = 30d;
// Regular expressions rather than has_any: the markers are followed by a host or slug in the same term (SageExec_ECPROOF...).
let CmdPattern = @"(?i)SAGE_(REMOTE_EXEC|EP_ADJUST|CA_EXPORT|CERT_ENROLL|CERT_AUTH)_PROOF|SagePfx-v1-|SageExec_|\\sage_(remote_exec|ep_adjust|ca_export_|ca_dpapi_|forged_cert_|ca_signing_|cert_enroll_|gpo_)";
let EncodedPrefix = "JABFAHIAcgBvAHIAQQBjAHQAaQBvAG4AUAByAGUAZgBlAHIAZQBuAGMAZQA9ACcAQwBvAG4AdABpAG4AdQBlACcAOwAkAGwAaQBuAGUAcwA9AE4AZQB3AC0ATwBiAGoAZQBjAHQAIABTAHkAcwB0AGUAbQAuAEMAbwBsAGwAZQBjAHQAaQBvAG4AcwAuAEcAZQBuAGUAcgBpAGMALgBMAGkAcwB0AFsAcwB0AHIAaQBuAGcAXQA7ACQAbABpAG4AZQBzAC4AQQBkAGQAKAAnAFMAQQBHAEUA";
let FilePattern = @"(?i)\\Windows\\Temp\\sage_(remote_exec|ep_adjust|ca_export_|ca_dpapi_|forged_cert_|ca_signing_)|\\sage_cert_enroll_|\\sage_gpo_[^\\]*_whoami\.txt$";
let ScriptPattern = @"SAGE_(REMOTE_EXEC|EP_ADJUST|CA_EXPORT|CERT_ENROLL|CERT_AUTH)_PROOF|New-PSDrive -Name SAGE(PROOF|EP|CA)\b|CERT_AUTH_METHOD=schannel-ldap|CERT_ENROLL_METHOD=native-certreq|DA_ONLY_READ_OP=domain-sacl|EP_REALTIME_BEFORE=";
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine matches regex CmdPattern or ProcessCommandLine contains EncodedPrefix
        | project TimeGenerated=Timestamp, DeviceName, Signal="Sage marker, proof path or SageExec task in a command line",
            Detail=strcat(InitiatingProcessFileName, " -> ", substring(ProcessCommandLine, 0, 300))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex FilePattern
        | project TimeGenerated=Timestamp, DeviceName, Signal="Sage proof or certificate file", Detail=strcat(InitiatingProcessFileName, " wrote ", FolderPath)),
    (SecurityEvent
        | where TimeGenerated > ago(Window)
        | where EventID == 4698 and EventData contains "SageExec_"
        | project TimeGenerated, DeviceName=Computer, Signal="Scheduled task SageExec_ created", Detail=substring(EventData, 0, 300)),
    (Event
        | where TimeGenerated > ago(Window)
        | where EventLog == "Microsoft-Windows-PowerShell/Operational" and EventID == 4104
        | where EventData matches regex ScriptPattern or RenderedDescription matches regex ScriptPattern
        | project TimeGenerated, DeviceName=Computer, Signal="Sage marker script in PowerShell script block logging",
            Detail=substring(coalesce(RenderedDescription, EventData), 0, 300))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by DeviceName, Signal
| order by LastSeen desc

// Sage's Phoenix trace UI and its downloads in network and proxy logs
// Agentic attack detections by ThreatDefence (Sage (Mythic)). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1105 (Ingress Tool Transfer)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Sage source code (MythicAgents/sage, reviewed at cbff42f0):
//  - The embedded Arize Phoenix UI answers on TCP 6006 (OTLP gRPC on 4317) with no login by default; its traces hold every
//    prompt and tool result, which can include credentials. Traffic to 6006 from outside the Mythic host deserves a look.
//  - The SharpHound card makes the Mythic server fetch
//    https://github.com/SpecterOps/SharpHound/releases/download/v2.13.0/SharpHound_v2.13.0_windows_x86.zip with python-requests.
//  - The optional Slack notice goes to hooks.slack.com; its body ("Sage findings changed. Open Mythic to review.") is only
//    visible with decryption, so the Suricata rules cover it.
// Sage does not contact targets itself: target traffic is the Mythic payload's C2 and is not covered here.

let Window = 30d;
let HoundPath = "/SpecterOps/SharpHound/releases/download/v2.13.0/SharpHound_v2.13.0_windows_x86.zip";
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where RequestURL has HoundPath and RequestClientApplication startswith "python-requests/"
        | project TimeGenerated, Source="CommonSecurityLog", Signal="SharpHound 2.13.0 fetched by python-requests",
            Detail=strcat(SourceIP, " ", RequestURL)),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where DestinationPort == 6006 and RequestURL has_any ("/graphql", "/projects", "/favicon.ico")
        | project TimeGenerated, Source="CommonSecurityLog", Signal="Request to a Phoenix-style UI on 6006",
            Detail=strcat(SourceIP, " -> ", DestinationIP, " ", RequestURL)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "InboundConnectionAccepted" and LocalPort in (6006, 4317) and RemoteIPType == "Public"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Signal="Public connection to a Phoenix port",
            Detail=strcat(DeviceName, " ", RemoteIP, " -> ", tostring(LocalPort), " ", InitiatingProcessCommandLine))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Signal
| order by LastSeen desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Sage (Mythic)). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1047 (Windows Management Instrumentation), T1071.001 (Application Layer Protocol: Web Protocols)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Sage has no addresses or domains of its own and sends no telemetry; its rows are the
// markers, file names and command fragments its tasks leave on targets, its container image, and its files on the Mythic server.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "sage-mythic" | project value=tostring(SearchKey), type, confidence, actor, source;
let UriStrings = toscalar(IOC | where type in ("uri_string", "url") and confidence in ("high", "medium") | summarize make_list(value));
let HostStrings = toscalar(IOC | where type in ("file_name", "file_path", "string") and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (UriStrings)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=RequestURL, Detail=strcat(SourceIP, " -> ", DestinationIP)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (HostStrings)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FolderPath, Detail=strcat(DeviceName, " ", InitiatingProcessFileName))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Indicator
| order by LastSeen desc

// sapper-v2 running on a host you monitor
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the sapper-v2 source code (N1nEmAn/sapper-v2 at 7b75e6f1). sapper-v2 starts Claude Code (and Codex) sessions in
// tmux, types missions into them and keeps a shared engagement graph on disk:
//  - Every agent window runs "cd <dir> && claude ... --dangerously-skip-permissions 2>&1; echo DRIVE_PANE_EXITED; exec
//    sleep infinity" in tmux session sapper-cmd, sapper-tui or sapper-fleet.
//  - Missions are typed with tmux send-keys, so their text is in the command line ("You are the autonomous field commander
//    of a pentest campaign (TSecBench)", "You are an autonomous pentest operator in a CTF benchmark").
//  - Executor steps run claude -p with --append-system-prompt "You are an autonomous executor in a penetration-testing
//    fact-graph agent system".
//  - The graph lives in .sapper/ (project.json, facts/, intents/); the contest image uses /work/runs and /opt/sapper.
//  - sapper view --serve opens a board on TCP 8765 (loopback by default).
// The names need a code change; the run folder (SAPPER_ROOT) and the board port are settings.

let Window = 30d;
let Prompts = dynamic(["You are an autonomous executor in a penetration-testing fact-graph agent system",
    "You are the autonomous field commander of a pentest campaign (TSecBench)",
    "You are an autonomous pentest operator in a CTF benchmark", "You are a GENERAL (senior operator) on challenge",
    "/opt/sapper/docker/commander/"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "DRIVE_PANE_EXITED"
            or (ProcessCommandLine has "tmux" and ProcessCommandLine matches regex @"\s-[st]\s+['""]?sapper-(cmd|tui|fleet)\b")
            or ProcessCommandLine has_any (Prompts)
            or ProcessCommandLine matches regex @"(^|[/\s])sapper(\.py)?\s(.*\s)?(auto\s(.*\s)?--(minutes|skip-permissions)|bench\s(.*\s)?--(root|minutes)|view\s(.*\s)?--serve)\b"
        | project Timestamp, DeviceName, Signal="sapper-v2 agent window, tmux session, mission or CLI", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"/\.sapper/(facts|intents|hints)/" or FolderPath has "/opt/sapper/docker/commander/"
            or FolderPath has "/work/runs/pane-env/"
            or (FolderPath has "/.sapper/" and FileName in~ ("project.json", "arena.json", "ai-channel.txt", "ai-peers.json"))
            or FileName =~ "sapper-graph.html"
            or (FolderPath has "/work/runs/" and FileName in~ ("commander-state.md", "rotated.env"))
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".sapper")[0])
        | project Timestamp, DeviceName, Signal="sapper-v2 graph or run files", Detail=strcat(Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where InitiatingProcessCommandLine matches regex @"(^|[/\s])sapper(\.py)?\s(.*\s)?view\s(.*\s)?--serve"
        | project Timestamp, DeviceName, Signal="sapper-v2 board listening", Detail=strcat(LocalIP, ":", LocalPort),
            Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1071.001 (Application Layer Protocol: Web Protocols)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. sapper-v2 has no operator addresses, domains or user agents of its own: its rows
// are the board title and poll path, file names and paths, tmux session names and prompt strings from the code.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework matches regex @"(^|\s)sapper-v2(\s|$)" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let Paths = toscalar(IOC | where type in ("file_path", "file_name") and confidence in ("high", "medium") | summarize make_list(value));
let Uris = toscalar(IOC | where type == "uri_string" and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | mv-apply s=Strings to typeof(string) on (where ProcessCommandLine has s | take 1 | project Indicator=s)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FolderPath has_any (Paths)
        | mv-apply p=Paths to typeof(string) on (where FolderPath has p | take 1 | project Indicator=p)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Uris)
        | mv-apply u=Uris to typeof(string) on (where RequestURL has u | take 1 | project Indicator=u)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " -> ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (Uris)
        | mv-apply u=Uris to typeof(string) on (where csUriStem has u | take 1 | project Indicator=u)
        | project TimeGenerated, Source="W3CIISLog", Indicator, Detail=strcat(cIP, " ", csUriStem))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// sapper-v2 board and contest client in web and proxy logs
// Agentic attack detections by ThreatDefence (sapper-v2). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the sapper-v2 source code (N1nEmAn/sapper-v2 at 7b75e6f1). sapper-v2 sends nothing of its own to a target: its
// agents run stock Kali tools, which the behaviors hunts cover. What it does put on the wire:
//  - Its board (sapper view --serve) polls GET /__sapper_graph__/<24 hex>.json every 2 seconds while open. The board has
//    no login: a hit through your proxy is someone in your network watching an engagement, often on an exposed board.
//  - Its contest client sends the header BENCHMARK_TOKEN to /openapi/v1/challenges (start, submit, close, hint). Any
//    TSecBench contest agent does the same, so treat it as context: an autonomous contest agent runs in your network.
//    Header values are rarely logged; the path is shown for context and needs the BENCHMARK_TOKEN header to mean much.

union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has "/__sapper_graph__/" or RequestURL has "/openapi/v1/challenges"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=coalesce(DestinationHostName, DestinationIP),
            Signal=iff(RequestURL has "/__sapper_graph__/", "sapper-v2 board poll", "TSecBench API path (context)"), Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem startswith "/__sapper_graph__/"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Signal="sapper-v2 board poll", Detail=csUriStem),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteUrl has "/__sapper_graph__/"
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Src=DeviceName, Target=RemoteIP, Signal="sapper-v2 board poll",
            Detail=RemoteUrl)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10)
    by Source, Src, Target, Signal
| order by FirstSeen asc

// Shannon running on a host you monitor
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// From the Shannon source code (KeygraphHQ/shannon at 3760d2f9). Shannon is a Node.js CLI (npm @keygraph/shannon, or
// ./shannon in a clone) that reads an application's source code and attacks the running application with model-driven
// agents in a Docker worker container. It has no telemetry, so the host is where it shows:
//  - The operator runs npx @keygraph/shannon start -u <url> -r <repo> (or ./shannon start ...).
//  - The CLI starts Temporal (container shannon-temporal, image temporalio/temporal, ports 7233 and 8233 on 127.0.0.1)
//    and one worker per scan: docker run --name shannon-worker-<8 hex> --network shannon-net with the labels
//    shannon.workspace, shannon.task-queue and shannon.workflow-id, image keygraph/shannon:<version> (or shannon-worker),
//    running node apps/worker/dist/temporal/worker.js <url> <repo> --task-queue shannon-<hex> --workflow-id ...
//  - Inside it the agents drive Chromium with playwright-cli -s=agent1 to agent5, and the report is rendered with
//    typst compile ... --input brand=Shannon | AI Pentester by Keygraph.
//  - Files: <workspaces>/<host>_shannon-<ms>/.shannon/ (session.json, workflow.log, agents/*.log, deliverables/),
//    Security-Assessment-Report.pdf and .md at the run root, and ~/.shannon/config.toml in npx mode.
//  - --exp-php2shell runs a PHP crash probe from the CLI alone, without Docker.
// Container processes show on a Linux Docker host with Defender for Endpoint; on macOS and Windows only the CLI and
// docker commands do. What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Markers = dynamic(["@keygraph/shannon", "keygraph/shannon:", "--name shannon-worker-", "shannon.workspace=", "shannon.workflow-id=",
    "TEMPORAL_ADDRESS=shannon-temporal:7233", "brand=Shannon | AI Pentester by Keygraph"]);
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has_any (Markers)
            or ProcessCommandLine matches regex @"(^|[/\\\s])shannon[""']?\s+start\s(.*\s)?(-u|--url)[\s=]"
            or (ProcessCommandLine has "temporal/worker.js" and ProcessCommandLine has "--task-queue" and ProcessCommandLine has "--workflow-id")
            or ProcessCommandLine matches regex @"playwright-cli\s+(.*\s)?-s=agent[1-6](\s|$)"
        | extend Signal = iff(ProcessCommandLine has "--exp-php2shell", "Shannon php2shell crash probe", "Shannon CLI, worker container, browser or report renderer")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 300), 10), Timestamp=min(Timestamp) by DeviceName, Signal
        | project Timestamp, DeviceName, Signal, Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]\.shannon[/\\]"
        | where FileName in~ ("session.json", "workflow.log", "startup-error.json", "cli.config.json", "stealth.js", "config.toml")
            or FileName matches regex @"^[a-z_]+_(deliverable\.md|exploitation_queue\.json|exploitation_evidence\.md)$"
        | summarize Files=make_set(FileName, 15), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, ".shannon")[0])
        | project Timestamp, DeviceName, Signal="Shannon workspace files", Detail=strcat(Folder, ".shannon ", tostring(Files))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName in~ ("Security-Assessment-Report.pdf", "Security-Assessment-Report.md", "php2shell-report.json")
        | where FolderPath matches regex @"_shannon-\d+" or FileName =~ "php2shell-report.json"
        | project Timestamp, DeviceName, Signal="Shannon report", Detail=FolderPath)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". Shannon has no infrastructure of its own: its rows are user agents, docker images, file names, strings and
// the console port, so a match needs the context in the row. Low-confidence user agents are left out here.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "shannon" | project value=tostring(SearchKey), type, confidence, actor, source;
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Images = toscalar(IOC | where type == "docker_image" | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let Files = toscalar(IOC | where type == "file_name" and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestClientApplication has_any (UAs) or RequestURL has_any (Strings)
        | project TimeGenerated, Source="CommonSecurityLog", Indicator=coalesce(RequestClientApplication, RequestURL), Detail=strcat(SourceIP, " ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where replace_string(csUserAgent, "+", " ") has_any (UAs)
        | project TimeGenerated, Source="W3CIISLog", Indicator=replace_string(csUserAgent, "+", " "), Detail=strcat(cIP, " ", csUriStem)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Images) or ProcessCommandLine has_any (Strings)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=substring(ProcessCommandLine, 0, 200), Detail=DeviceName),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Files)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath))
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10) by Source, Indicator
| order by LastSeen desc

// Shannon testing you: the php2shell probe sizes and its browser user agent in web and proxy logs
// Agentic attack detections by ThreatDefence (Shannon). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1499.004 (Endpoint Denial of Service: Application or System Exploitation), T1595.002 (Active Scanning: Vulnerability Scanning)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Shannon source code (KeygraphHQ/shannon at 3760d2f9):
//  - shannon start --exp-php2shell -u <url> sends three POSTs to the same URL: a 181-byte multipart control, a
//    1,029,023-byte probe and, unless that one already crashed the worker, a 7,449,023-byte probe. Both probes are one
//    multipart part with 80,000 or 540,000 headers X-h0: a, X-h1: a, ... and the boundary ----shannonPhp2shellProbe<32 hex>.
//    The body sizes are exact; logged byte counts add the request line and headers (a few hundred bytes).
//  - Its agents browse with a fixed user agent, Chrome 124 on Linux. Real Chrome 124 sends the same string, so it only
//    counts next to other signs of testing from the same address.
// A probe pair against a PHP site means someone checked it for the php2shell crash; the Suricata rules see the boundary.

let Window = 30d;
let ShannonUA = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36";
union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where csMethod == "POST" and (csBytes between (1029023 .. 1031023) or csBytes between (7449023 .. 7451023))
        | summarize Probes=count(), Sizes=make_set(csBytes, 5), Statuses=make_set(scStatus, 5), Timestamp=min(TimeGenerated) by Src=cIP, Target=csHost, Path=csUriStem
        | project Timestamp, Source="W3CIISLog", Src, Target, Signal="php2shell probe sizes", Detail=strcat(Path, " sizes ", tostring(Sizes), " status ", tostring(Statuses))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestMethod == "POST" and (ReceivedBytes between (1029023 .. 1031023) or ReceivedBytes between (7449023 .. 7451023))
        | summarize Probes=count(), Sizes=make_set(ReceivedBytes, 5), Timestamp=min(TimeGenerated) by Src=SourceIP, Target=DestinationHostName, Path=RequestURL
        | project Timestamp, Source="CommonSecurityLog", Src, Target, Signal="php2shell probe sizes", Detail=strcat(Path, " sizes ", tostring(Sizes))),
    (W3CIISLog | where TimeGenerated > ago(Window)
        | where replace_string(csUserAgent, "+", " ") == ShannonUA
        | summarize Requests=count(), Paths=dcount(csUriStem), Samples=make_set(csUriStem, 10), Timestamp=min(TimeGenerated) by Src=cIP, Target=csHost
        | project Timestamp, Source="W3CIISLog", Src, Target, Signal="Shannon browser user agent (context)", Detail=strcat(Requests, " requests, ", Paths, " paths ", tostring(Samples))),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where RequestClientApplication == ShannonUA
        | summarize Requests=count(), Samples=make_set(RequestURL, 10), Timestamp=min(TimeGenerated) by Src=SourceIP, Target=DestinationHostName
        | project Timestamp, Source="CommonSecurityLog", Src, Target, Signal="Shannon browser user agent (context)", Detail=strcat(Requests, " requests ", tostring(Samples)))
| order by Timestamp desc

// Strix running on a host you monitor
// Agentic attack detections by ThreatDefence (Strix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test before alerting.
// From the Strix source code (usestrix/strix at a1ccf777). Strix is a Python CLI, pip package strix-agent, that runs its
// agents' commands in a Docker sandbox:
//  - The operator runs: strix --target <url> [--scan-mode quick|standard|deep] [--non-interactive] (deep is the default;
//    Gambit saw 146 deep-mode runs against 138 hosts in the retail card-theft campaign).
//  - It pulls ghcr.io/usestrix/strix-sandbox (Kali with nmap, nuclei, sqlmap, ffuf, katana, httpx, interactsh-client)
//    and labels the container strix-run-id. Inside, caido-cli --listen 0.0.0.0:48080 --allow-guests proxies every tool.
//  - Results land in ./strix_runs/<run>/: run.json, agents.json, vulnerabilities.json, vulnerabilities.csv, coverage.json,
//    findings.sarif and penetration_test_report.md.
//  - Telemetry is on by default: strix.gateway.scarf.sh and us.i.posthog.com on every scan.
// The model can be anything LiteLLM reaches; Gambit's operator ran GLM 5.2 and DeepSeek v4 Pro through OpenRouter, which
// behaviors hunt 02 covers. Names and paths need a code change, apart from the image tag and the run folder location.

let Window = 30d;
union isfuzzy=true
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where (ProcessCommandLine matches regex @"(^|[/\\\s])strix(\.exe)?\s" and ProcessCommandLine matches regex @"\s(--target|-t|--target-list|--scan-mode|--resume)[\s=]")
            or ProcessCommandLine matches regex @"((pip|pip3|pipx)\s+install|uv\s+(tool\s+install|tool\s+run|pip\s+install)|uvx)\s(.*\s)?[""']?strix-agent" or ProcessCommandLine contains "usestrix/strix-sandbox"
            or (ProcessCommandLine contains "caido-cli" and ProcessCommandLine contains "--allow-guests")
        | project Timestamp, DeviceName, Signal="Strix command, install or sandbox", Detail=substring(ProcessCommandLine, 0, 300),
            Parent=strcat(InitiatingProcessFileName, " ", substring(InitiatingProcessCommandLine, 0, 150))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath matches regex @"[/\\]strix_runs[/\\]"
            and FileName in~ ("run.json", "agents.json", "vulnerabilities.json", "vulnerabilities.csv", "findings.sarif", "penetration_test_report.md")
        | summarize Files=make_set(FileName, 10), Timestamp=min(Timestamp) by DeviceName, Folder=tostring(split(FolderPath, "strix_runs")[1])
        | project Timestamp, DeviceName, Signal="Strix run folder", Detail=strcat("strix_runs", Folder, " ", tostring(Files)), Parent=""),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where RemoteUrl has "strix.gateway.scarf.sh"
        | project Timestamp, DeviceName, Signal="Strix telemetry", Detail=RemoteUrl, Parent=InitiatingProcessCommandLine)
| order by Timestamp desc

// Strix telemetry and results viewers seen from your network
// Agentic attack detections by ThreatDefence (Strix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. DNS works everywhere; URL paths need a proxy that records full URLs. Test before alerting.
// From the Strix source code. Every scan reports itself unless the operator sets STRIX_TELEMETRY=false:
//  - POST https://strix.gateway.scarf.sh/scan_started/<version>?..., /finding_reported/<version>?severity=<level>&cwe=...
//    and /scan_ended/<version> (strix/telemetry/scarf.py). A finding_reported call means Strix just found something.
//  - POST https://us.i.posthog.com/capture/ with the project key phc_7rO3XRuNT5sgSKAl6HDIrWdSGh1COzxw0vxVIAR6vVZ.
// The results viewer (strix_runs browser) serves a page titled "Strix Results" with /api/runs, /api/run and
// /api/agents/steer, on 127.0.0.1 and a random port by default; GitGuardian found 13 exposed, on 8080.
// A machine on your network sending Strix telemetry is running Strix: an authorized test, or someone attacking from inside.

let Window = 30d;
union isfuzzy=true
    (DnsEvents
        | where TimeGenerated > ago(Window)
        | where Name has "strix.gateway.scarf.sh"
        | summarize Queries=count(), Timestamp=min(TimeGenerated) by Src=ClientIP
        | project Timestamp, Src, Signal="DNS for Strix telemetry", Detail=strcat("x", Queries)),
    (CommonSecurityLog
        | where TimeGenerated > ago(Window)
        | where DestinationHostName has "strix.gateway.scarf.sh" or RequestURL contains "strix.gateway.scarf.sh"
            or (RequestURL contains "/api/agents/steer" or RequestURL endswith "/api/runs")
        | extend Event = extract(@"scarf\.sh/([a-z_]+)/", 1, RequestURL), Severity = extract(@"severity=([a-z]+)", 1, RequestURL)
        | summarize Requests=count(), Events=make_set(Event, 5), Severities=make_set(Severity, 5), URLs=make_set(RequestURL, 5),
            Timestamp=min(TimeGenerated) by Src=SourceIP
        | project Timestamp, Src, Signal="Strix telemetry or viewer API through the proxy",
            Detail=strcat("events ", tostring(Events), " finding severities ", tostring(Severities), " ", tostring(URLs)))
| order by Timestamp desc

// Vigilo on a host you monitor
// Agentic attack detections by ThreatDefence (Vigilo). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Vigilo (certeu/vigilo, reviewed at 82c2d353, v1.0.0) is a CERT-EU platform for AI-driven assessment of your own
// applications. This hunt finds where it runs, from its source code:
//  - Processes: python -m src.webapi.main (API on 8080, internal listener on 8081), python -m src.greybox_web.worker,
//    python -m src.temporal.worker --serve --task-queue vigilo-pipeline or vigilo-<12 hex>.
//  - White-box agents: claude -p <prompt> --dangerously-skip-permissions (or codex exec / opencode run) whose prompt
//    contains "authorised security assessment run by Vigilo", and the helper commands vigilo-record and save-deliverable.
//  - Files: <repo>/.vigilo/<session>/(agents|prompts|deliverables)/, <repo>/.vigilo-remote-url,
//    .git/vigilo-delivery.json and .git/vigilo-rebuild.json.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Platform = dynamic(["src.temporal.worker --serve --task-queue vigilo-", "-m src.greybox_web.worker", "-m src.webapi.main",
    "/usr/local/bin/vigilo-record", "vigilo-record show ", "vigilo-record verdict ", "vigilo-record lead "]);
let VgProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where ProcessCommandLine has_any (Platform)
        or (ProcessCommandLine has "authorised security assessment run by Vigilo"
            and ProcessCommandLine has_any ("--dangerously-skip-permissions", "--dangerously-bypass-approvals-and-sandbox"));
let VgDevices = VgProcesses | distinct DeviceName;
union isfuzzy=true
    (VgProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Vigilo platform process, white-box agent or helper command", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where (FolderPath has "/.vigilo/" and FolderPath has_any ("/deliverables/", "/agents/", "/prompts/"))
            or FolderPath endswith "/.vigilo-remote-url" or FolderPath endswith "/.git/vigilo-delivery.json"
            or FolderPath endswith "/.git/vigilo-rebuild.json"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Vigilo run folder, deliverables or delivery state", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where LocalPort in (8080, 8081) and InitiatingProcessCommandLine has "src.webapi.main"
        | summarize Ports=make_set(LocalPort, 10), Timestamp=min(Timestamp) by DeviceName, LocalIP
        | project Timestamp, DeviceName, Signal="Vigilo API listening", Detail=strcat(LocalIP, " ", tostring(Ports)))
| extend KnownVigiloDevice = DeviceName in (VgDevices)
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Vigilo). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595 (Active Scanning), T1071 (Application Layer Protocol)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. Addresses are reassigned, so check the reported date and review_by.
// Vigilo has no infrastructure of its own (it is self-hosted), so these rows are fingerprints of the software: its
// user agents and markers. A match means a Vigilo assessment; check that it was agreed.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "vigilo" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" and confidence in ("high", "medium") | summarize make_list(value));
let Strings = toscalar(IOC | where type in ("string", "uri_string") and confidence == "high" | summarize make_list(value));
union isfuzzy=true
    (SigninLogs | where TimeGenerated > ago(90d)
        | where IPAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="SigninLogs", Indicator=coalesce(IPAddress, UserAgent), Detail=UserPrincipalName),
    (AWSCloudTrail | where TimeGenerated > ago(90d)
        | where SourceIpAddress in (IPList) or UserAgent has_any (UAs)
        | project TimeGenerated, Source="AWSCloudTrail", Indicator=SourceIpAddress, Detail=strcat(EventName, " ", UserIdentityArn)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication has_any (UAs) or RequestURL has_any (Strings)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where cIP in (IPList) or replace_string(csUserAgent, "+", " ") has_any (UAs) or csUriQuery has_any (Strings)
        | project TimeGenerated, Source="W3CIISLog", Indicator=cIP, Detail=strcat(csUriStem, "?", csUriQuery)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=RemoteIP,
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// Vigilo assessments reaching you: its user agents and probe markers in web and proxy logs
// Agentic attack detections by ThreatDefence (Vigilo). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Vigilo source code (certeu/vigilo, reviewed at 82c2d353, v1.0.0):
//  - Every grey-box request carries User-Agent: Vigilo-Greybox/1 (authorised security test);
//    every white-box run with a target starts with HEAD / and User-Agent: Vigilo-Preflight/1.0.
//  - Grey-box probes: redirect parameters set to https://vigilo-probe-<8 hex>.invalid/, the reflection canary
//    vgl<8 hex>"'<>b (vgl<8 hex>%22%27%3C%3Eb in logs), the soft-404 path /vgl-<8 hex>, callback check tokens
//    vigilo-callback-<8 hex> and vigilo-control-<8 hex>.
//  - After the preflight, white-box agents use curl, headless Chromium, WhatWeb and schemathesis with their own user
//    agents: the second part of this hunt lists what the same source sent after a Vigilo marker.
// Vigilo is a CERT-EU tool for assessing your own applications. Confirm the assessment was agreed.

let Window = 30d;
let UAPrefixes = dynamic(["Vigilo-Greybox/", "Vigilo-Preflight/"]);
let QueryMarkers = dynamic(["vigilo-probe-", "vigilo-callback-", "vigilo-control-", "%22%27%3C%3Eb"]);
let Web = union isfuzzy=true
    (W3CIISLog | where TimeGenerated > ago(Window)
        | extend UA=replace_string(csUserAgent, "+", " ")
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Path=csUriStem, Query=csUriQuery, UA),
    (CommonSecurityLog | where TimeGenerated > ago(Window)
        | where isnotempty(RequestURL)
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Path=RequestURL,
            Query="", UA=RequestClientApplication);
let Marked = Web
    | where UA startswith "Vigilo-Greybox/" or UA startswith "Vigilo-Preflight/"
        or Query has_any (QueryMarkers) or Path has_any (QueryMarkers)
        or Path matches regex @"(^|/)vgl-[0-9a-f]{8}$";
let VgSources = Marked | summarize MarkerFirst=min(TimeGenerated) by Src, Target;
union
    (Marked
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated),
            Samples=make_set(strcat(Path, iff(isempty(Query), "", strcat("?", Query))), 10), UAs=make_set(UA, 5) by Source, Src, Target
        | extend Signal="Vigilo user agent or probe marker"),
    (Web
        | join kind=inner (VgSources) on Src, Target
        | where TimeGenerated between (MarkerFirst .. (MarkerFirst + 1d))
        | where not(UA startswith "Vigilo-Greybox/" or UA startswith "Vigilo-Preflight/")
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated),
            Samples=make_set(Path, 10), UAs=make_set(UA, 5) by Source, Src, Target
        | extend Signal="Other requests from the same source within a day of a Vigilo marker")
| order by Src asc, FirstSeen asc

// Virga C2 server, operator CLI or beacon builds on a host you monitor
// Agentic attack detections by ThreatDefence (Virga). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1587.001 (Develop Capabilities: Malware), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Virga (r74tech/virga, reviewed at 43773ffe) is a Go C2 framework whose beacon can carry a local language model. No
// report of its use in a real intrusion was found on November 26, 2026, so this hunt looks for the software itself:
//  - virga-server, virga-cli, virga-mcp-stdio (bin/ or ~/.local/bin), and MCP Inspector started with --server virga-*.
//  - Beacon builds: go build / link with -X ...internal/implant/config.BuildC2Host=<host> and -tags llama_selfextract.
//  - Files: /tmp/virga/extensions/, data/virga.db, .virga_history, virga-generator-<random>, the model.gguf it embeds.
//  - Listening sockets opened by virga-server: 8443 admin API, 8080 listener, 8444 and 50012 MCP (all without auth).
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let VirgaBinaries = dynamic(["virga-server", "virga-cli", "virga-mcp-stdio", "virga-server.exe", "virga-cli.exe"]);
let BuildMarkers = dynamic(["internal/implant/config.BuildC2Host=", "internal/implant/config.BuildLlamaEnabled="]);
let VirgaProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ (VirgaBinaries) or FileName startswith "virga-server-" or FileName startswith "virga-cli-"
        or ProcessCommandLine has_any (BuildMarkers)
        or (ProcessCommandLine has "llama_selfextract,prebuilt" and ProcessCommandLine has "internal/implant/main.go")
        or ProcessCommandLine has_any ("--server virga-stdio", "--server virga-sse", "--server virga-streamable");
union isfuzzy=true
    (VirgaProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 300), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Virga server, CLI, MCP server or beacon build", Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath startswith "/tmp/virga/extensions/" or FolderPath endswith "/data/virga.db" or FileName =~ ".virga_history"
            or FolderPath has "/virga-generator-" or FolderPath has @"\virga-generator-"
            or FolderPath endswith "/internal/implant/llama/models/model.gguf" or FolderPath endswith @"\internal\implant\llama\models\model.gguf"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Virga server data, generator folder or embedded model", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated"
        | where InitiatingProcessFileName in~ (VirgaBinaries) or InitiatingProcessFileName startswith "virga-server-"
        | summarize Ports=make_set(LocalPort, 10), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="Ports opened by the Virga server (8443, 8080, 8444, 50012 by default)",
            Detail=strcat(InitiatingProcessFileName, " ", tostring(Ports)))
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (Virga). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1587.001 (Develop Capabilities: Malware)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. No Virga infrastructure has been published, so its rows are the beacon user
// agents, the listener and MCP paths, its file and binary names, and the download URLs of its model bindings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "virga" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Names = toscalar(IOC | where type == "file_name" and confidence in ("high", "medium") | summarize make_list(value));
let MD5s = toscalar(IOC | where type == "md5" | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication in (UAs) or DestinationHostName has_any (Domains)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication in (UAs), RequestClientApplication, DestinationHostName)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=iff(RemoteIP in (IPList), RemoteIP, RemoteUrl),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where FileName in~ (Names) or MD5 in~ (MD5s)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=iff(FileName in~ (Names), FileName, tolower(MD5)),
            Detail=strcat(DeviceName, " ", FolderPath)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Names) or MD5 in~ (MD5s)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=iff(FileName in~ (Names), FileName, tolower(MD5)),
            Detail=strcat(DeviceName, " ", FolderPath)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// Virga beacon check-ins, stage 2 requests and console calls in proxy and web logs
// Agentic attack detections by ThreatDefence (Virga). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1105 (Ingress Tool Transfer)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Virga listener and admin API (r74tech/virga, reviewed at 43773ffe):
//  - A beacon POSTs a Base64 body to /api/updates (the default uri_path) every few seconds (10 s with jitter 20 % in
//    the shipped beacon.yaml, 1 s in interactive mode). Its user agent is the Chrome 96 string the generator uses
//    without a config, or the truncated "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" from
//    beacon.yaml (also used by CyberStrikeAI, AutoPT and GH05TCREW PentestAgent). Both are settings.
//  - GET /api/updates/stage2 fetches the stage 2 payload.
//  - Requests from your network to /api/forest, /api/sessions/<id>/killswitch, /mcp/events or /mcp on another host
//    are someone driving a Virga server.
// Beacons on a fixed interval show as many events per hour from one source to one URL.

let UAs = dynamic(["Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/96.0.4664.110 Safari/537.36",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"]);
let Console = @"/api/forest$|/api/sessions/[^/]+/(killswitch|beacon-config|chat|extensions)|/mcp/events$|/mcp/message\?";
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(30d)
        | extend Path = tostring(split(tostring(split(RequestURL, "?")[0]), "#")[0])
        | where (RequestMethod =~ "POST" and Path endswith "/api/updates" and RequestClientApplication in (UAs))
            or Path endswith "/api/updates/stage2"
            or RequestURL matches regex Console
        | extend Signal = case(Path endswith "/api/updates/stage2", "stage 2 request", Path endswith "/api/updates", "beacon check-in", "Virga console or MCP call")
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), URLs=make_set(RequestURL, 5),
            UAs=make_set(RequestClientApplication, 3) by Source="CommonSecurityLog", Src=SourceIP, Dst=DestinationHostName, Signal),
    (W3CIISLog
        | where TimeGenerated > ago(30d)
        | extend UA = replace_string(csUserAgent, "+", " ")
        | where (csMethod =~ "POST" and csUriStem endswith "/api/updates" and UA in (UAs)) or csUriStem endswith "/api/updates/stage2"
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), URLs=make_set(csUriStem, 5),
            UAs=make_set(UA, 3) by Source="W3CIISLog", Src=cIP, Dst=sSiteName, Signal="beacon traffic through an IIS redirector")
| extend PerHour = round(todouble(Events) / max_of(1.0, (LastSeen - FirstSeen) / 1h), 1)
| order by Events desc

// Executables over 1.5 GB that talk on the network: beacons that carry a local language model
// Agentic attack detections by ThreatDefence (Virga). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1587.001 (Develop Capabilities: Malware)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Virga's generator appends the whole GGUF model (Qwen3-4B Q4_K_M by default, about 2.5 GB) to the beacon and writes
// its size in the last 8 bytes, so a Virga beacon with its model is a single executable of several gigabytes that
// beacons out over HTTP. Very few legitimate programs are that large in one file; games, IDEs and local AI tools are
// the usual exceptions. Check the folder, the signer and what the process connects to. The YARA rule
// Virga_Beacon_With_Appended_GGUF_Model confirms the layout if the scanner reads files of this size.

let Window = 14d;
let MinSize = 1536 * 1024 * 1024;
union isfuzzy=true
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where InitiatingProcessFileSize > MinSize
        | where ActionType in ("ConnectionSuccess", "ConnectionAttempt", "ConnectionRequest")
        | summarize Connections=count(), Remotes=make_set(strcat(RemoteIP, ":", RemotePort), 10), Timestamp=min(Timestamp)
            by DeviceName, InitiatingProcessFileName, InitiatingProcessFolderPath, InitiatingProcessFileSize
        | project Timestamp, DeviceName, Signal="Executable over 1.5 GB with network connections",
            Detail=strcat(InitiatingProcessFolderPath, " (", tostring(InitiatingProcessFileSize / 1048576), " MB) -> ", tostring(Remotes))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileSize > MinSize
        | where FileName endswith ".exe" or FileName endswith ".elf" or FolderPath has_any ("/tmp/", @"\Temp\", @"\Downloads\", @"\ProgramData\", @"\Users\Public\")
        | where not(FileName has_any (".gguf", ".bin", ".safetensors", ".iso", ".vhd", ".zip", ".7z", ".tar", ".gz"))
        | project Timestamp, DeviceName, Signal="Executable over 1.5 GB written",
            Detail=strcat(FolderPath, " (", tostring(FileSize / 1048576), " MB) by ", InitiatingProcessFileName))
| order by Timestamp desc

// VulnBot on a host you monitor: the controller and the Kali host it drives
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1059.004 (Command and Scripting Interpreter: Unix Shell), T1021.004 (Remote Services: SSH), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// VulnBot (KHenryAegis/VulnBot, reviewed at 9a12effa) is a Python CLI whose three agents (reconnaissance, scanning,
// exploitation) run every command in one SSH shell on a separate Kali host. No report of its use in a real intrusion
// was found on November 26, 2026, so this hunt looks for the software itself, from its source code:
//  - Controller: python cli.py vulnbot -m <n> [-t <s>], cli.py start -a (API on 7861, Streamlit on 8501), cli.py init.
//  - Kali host: right after an SSH password login (default root/root) the shell runs touch ~/.hushlogin,
//    sudo touch /etc/legal, sudo chmod 644 /etc/legal, sudo rm -f /etc/motd, sudo rm -f /etc/update-motd.d/*, then
//    the Kali tools the model chose (nmap, nikto, dirb, sqlmap, hydra, msfconsole and others).
//  - Files: logs/Auto-Pentest.log, basic_config.yaml, model_config.yaml, kb_config.yaml, db_config.yaml in its folder.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let SetupCommands = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where (FileName in~ ("touch", "chmod", "sudo") and ProcessCommandLine has "/etc/legal")
        or (FileName in~ ("rm", "sudo") and ProcessCommandLine has "-f" and ProcessCommandLine has_any ("/etc/motd", "/etc/update-motd.d/"))
        or (FileName =~ "touch" and ProcessCommandLine endswith "/.hushlogin");
union isfuzzy=true
    (SetupCommands
        | summarize Steps=dcount(case(ProcessCommandLine has "/etc/legal", "legal", ProcessCommandLine has "motd", "motd", "hushlogin")),
            Commands=make_set(ProcessCommandLine, 10), First=min(Timestamp) by DeviceName, AccountName, Bucket=bin(Timestamp, 2m)
        | where Steps >= 2
        | project Timestamp=First, DeviceName, Signal="VulnBot SSH shell setup on the host it drives", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where ProcessCommandLine has "cli.py" and ProcessCommandLine has_any (" vulnbot", " pentestgpt", " start -a", "VulnBot/cli.py", "VulnBot\\cli.py")
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName, AccountName
        | project Timestamp, DeviceName, Signal="VulnBot command line", Detail=strcat(AccountName, " ", tostring(Commands))),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FileName =~ "Auto-Pentest.log" or (FolderPath has "/logs/run_api_server_" or FolderPath has "/logs/run_webui_")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="VulnBot log files", Detail=tostring(Files))
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation.
// No VulnBot infrastructure has been published, so these rows are fingerprints of the software: its prompts, its
// command lines, its log file name and the shell setup it runs on the Kali host it drives.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "vulnbot" | project value=tostring(SearchKey), type, confidence, actor, source;
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
let FileNames = toscalar(IOC | where type == "file_name" | summarize make_list(value));
let Paths = toscalar(IOC | where type == "uri_string" | summarize make_list(value));
union isfuzzy=true
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where ProcessCommandLine has_any (Strings)
        | extend Indicator=Strings | mv-expand Indicator to typeof(string) | where ProcessCommandLine contains Indicator
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator, Detail=strcat(DeviceName, " ", substring(ProcessCommandLine, 0, 200))),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (FileNames)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (Paths)
        | extend Indicator=Paths | mv-expand Indicator to typeof(string) | where RequestURL contains Indicator
        | project TimeGenerated, Source="CommonSecurityLog", Indicator, Detail=strcat(SourceIP, " -> ", RequestURL)),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (Paths)
        | extend Indicator=Paths | mv-expand Indicator to typeof(string) | where csUriStem contains Indicator
        | project TimeGenerated, Source="W3CIISLog", Indicator, Detail=strcat(cIP, " ", csUriStem))
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// VulnBot in web and proxy logs: its open knowledge base API and the models it downloads
// Agentic attack detections by ThreatDefence (VulnBot). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1071.001 (Application Layer Protocol: Web Protocols), T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// VulnBot sends no marker of its own to the targets it tests: its traffic is the Kali tools the model picks. What
// does show in web and proxy logs, from the source code (KHenryAegis/VulnBot, reviewed at 9a12effa):
//  - Its knowledge base API (FastAPI, port 7861, bound to 0.0.0.0, no authentication) under /knowledge_base/:
//    list_knowledge_bases, create_knowledge_base, upload_docs, search_docs, download_doc and others. The Streamlit page
//    on 8501 calls it. Langchain-Chatchat, which this code comes from, has the same paths, so check the host.
//  - Hugging Face downloads of maidalun1020/bce-embedding-base_v1 and maidalun1020/bce-reranker-base_v1, its default
//    embedding and reranking models (other RAG tools use them too: context only).
// Its prompts appear only in model traffic you can read (AI gateway logs, TLS inspection); see the Suricata rules.

let ApiPaths = dynamic(["/knowledge_base/list_knowledge_bases", "/knowledge_base/create_knowledge_base", "/knowledge_base/upload_docs",
    "/knowledge_base/search_docs", "/knowledge_base/download_doc", "/knowledge_base/delete_knowledge_base"]);
let Models = dynamic(["maidalun1020/bce-embedding-base_v1", "maidalun1020/bce-reranker-base_v1"]);
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where RequestURL has_any (ApiPaths) or (DestinationHostName has "huggingface.co" and RequestURL has_any (Models))
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=coalesce(DestinationHostName, DestinationIP),
            Port=DestinationPort, Detail=RequestURL),
    (W3CIISLog | where TimeGenerated > ago(90d)
        | where csUriStem has_any (ApiPaths)
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Port=sPort, Detail=strcat(csMethod, " ", csUriStem, "?", csUriQuery))
| extend Signal=iff(Detail has "maidalun1020", "VulnBot default RAG model download (context only)", "VulnBot knowledge base API path")
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10), Ports=make_set(Port, 5)
    by Source, Signal, Src, Target
| order by FirstSeen asc

// Xalgorix on a host you monitor
// Agentic attack detections by ThreatDefence (Xalgorix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// Xalgorix (xalgorix/xalgorix) is a Go binary with a web dashboard on port 9137 whose agent runs a penetration test
// without asking for approval. No report of its use in a real intrusion was found on November 23, 2026, so this hunt
// looks for the software itself, from its source code:
//  - The binary (xalgorix --web) or the image xalgord/xalgorix, run privileged with the volume xalgorix-data.
//  - Every command the agent runs is bash -c with a wrapper that starts export XALGORIX_WORKSPACE=... and defines
//    __xalgorix_resolve_path. As root on Linux it also uses xalgorix-scan-init and nsenter.
//  - Its browser: Chromium with --no-sandbox --disable-web-security --allow-running-insecure-content.
//  - Files: ~/.xalgorix.env, /etc/xalgorix.env, ~/.xalgorix/data/<target>/, /etc/systemd/system/xalgorix.service.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let Wrapper = dynamic(["XALGORIX_WORKSPACE=", "__xalgorix_resolve_path", "xalgorix-scan-init", "xalgord/xalgorix", "xalgorix --web"]);
let XalgorixProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName =~ "xalgorix" or ProcessCommandLine has_any (Wrapper);
let XalgorixDevices = XalgorixProcesses | distinct DeviceName;
union isfuzzy=true
    (XalgorixProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 200), 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Xalgorix binary, image or agent shell wrapper", Detail=tostring(Commands)),
    (DeviceProcessEvents
        | where Timestamp > ago(Window)
        | where DeviceName in (XalgorixDevices)
        | where ProcessCommandLine has "--disable-web-security" and ProcessCommandLine has "--allow-running-insecure-content"
        | summarize Runs=count(), Timestamp=min(Timestamp) by DeviceName, FileName
        | project Timestamp, DeviceName, Signal="Browser with web security off on a device that runs Xalgorix", Detail=strcat(FileName, " x", Runs)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath has "/.xalgorix/data/" or FileName =~ ".xalgorix.env" or FolderPath in~ ("/etc/xalgorix.env", "/etc/systemd/system/xalgorix.service")
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="Xalgorix configuration, service or scan data", Detail=tostring(Files))
| order by Timestamp desc

// Xalgorix testing you: its verifier paths, canary and user agents in web and proxy logs
// Agentic attack detections by ThreatDefence (Xalgorix). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the Xalgorix source code (xalgorix/xalgorix, reviewed at f5b1a99a):
//  - When its verifier confirms a finding it requests <path>-xalgorix-nonexistent-<id> (access control) and
//    <dir>/xalgorix-missing-<id> followed by ../ steps to etc/passwd (path traversal). These strings are in the code.
//  - The reflection canary XALG0R1XTEST is an example in its system prompt, so the model may use another string.
//  - Its own user agents start with xalgorix (xalgorix-origin-calibration/1, xalgorix/<version>).
// A verifier marker means a finding was being confirmed: look at what the same source requested just before it.

let Markers = @"xalgorix-nonexistent-|xalgorix-missing-|XALG0R1XTEST";
union isfuzzy=true
    (W3CIISLog | extend UA=replace_string(csUserAgent, "+", " ")
        | where csUriStem matches regex Markers or csUriQuery matches regex Markers or UA startswith "xalgorix"
        | project TimeGenerated, Source="W3CIISLog", Src=cIP, Target=csHost, Detail=strcat(csUriStem, "?", csUriQuery), UA),
    (CommonSecurityLog | where RequestURL matches regex Markers or RequestClientApplication startswith "xalgorix"
        | project TimeGenerated, Source="CommonSecurityLog", Src=SourceIP, Target=DestinationHostName, Detail=RequestURL, UA=RequestClientApplication)
| where TimeGenerated > ago(90d)
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Samples=make_set(Detail, 10),
    UAs=make_set(UA, 5) by Source, Src, Target
| order by FirstSeen asc

// 0security CLI, web console, remote engine or live-target tests on a host you monitor
// Agentic attack detections by ThreatDefence (0security). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1588.002 (Obtain Capabilities: Tool), T1595.002 (Active Scanning: Vulnerability Scanning), T1059.004 (Command and Scripting Interpreter: Unix Shell)
// Example hunt for Defender XDR advanced hunting. Test and baseline before alerting.
// 0security (0sec-labs/0security, reviewed at eec0d4c7) is an agent harness that reviews code, fixes findings and can
// test live targets. It is sold to security teams, so a hit is first a question of who runs it and against what:
//  - Binaries: ~/.0/bin/0security (and the alias 0), 0security-<platform>, the older 0-<platform>; Docker: node /app/dist/0.js.
//  - Console: `0security web` or bare `0security` on 127.0.0.1:48123; the Docker image runs --host 0.0.0.0 --server-mode.
//  - Live targets: `0 probe <url>` (adversarial prompts to a model endpoint; --i-own-this for a public host) and
//    `0 scan --scanner nuclei --target-url <url>` (Nuclei with -jle <tmp>/0-nuclei-<random>/results.jsonl).
//  - Remote engine over SSH: /tmp/zero-engine, --engine-token-env ZERO_WORKER_TOKEN, an ssh -N -L <port>:127.0.0.1:<port> tunnel.
//  - Files: ~/.0/0.db, ~/.0/access-token, ~/.0/analytics-id, ~/.0/analytics-sent.log, ~/.0/runs/; verifier containers 0-verify-<hex>.
// What each signal relies on in the source is in ../../source-code-signals.md.

let Window = 30d;
let ZeroImages = dynamic(["0security", "0security-linux-x64", "0security-linux-arm64", "0security-darwin-arm64", "0security-windows-x64.exe",
    "0-linux-x64", "0-linux-arm64", "0-darwin-arm64", "0-windows-x64.exe"]);
let ZeroProcesses = DeviceProcessEvents
    | where Timestamp > ago(Window)
    | where FileName in~ (ZeroImages) or FolderPath endswith "/.0/bin/0security"
        or ProcessCommandLine contains "/app/dist/0.js"
        or ProcessCommandLine contains "--engine-token-env ZERO_WORKER_TOKEN"
        or ProcessCommandLine contains "/tmp/zero-engine"
        or (ProcessCommandLine contains "0-nuclei-" and ProcessCommandLine contains "-etags intrusive,dos,fuzz")
        or (ProcessCommandLine contains "--name 0-verify-" and ProcessCommandLine contains "0.verify=1")
    | extend Activity = case(
        ProcessCommandLine contains " probe http" or ProcessCommandLine contains "--i-own-this", "probe of a live model endpoint",
        ProcessCommandLine contains "--target-url" or ProcessCommandLine contains "0-nuclei-", "Nuclei scan of a live target",
        ProcessCommandLine contains "--server-mode", "console in server mode (network)",
        ProcessCommandLine contains "ZERO_WORKER_TOKEN" or ProcessCommandLine contains "/tmp/zero-engine", "engine deployed to a remote computer",
        ProcessCommandLine contains "0-verify-", "verification container",
        "0security CLI or console");
union isfuzzy=true
    (ZeroProcesses
        | summarize Commands=make_set(substring(ProcessCommandLine, 0, 300), 10), Timestamp=min(Timestamp) by DeviceName, AccountName, Activity
        | project Timestamp, DeviceName, Signal=strcat("0security: ", Activity), Detail=tostring(Commands)),
    (DeviceFileEvents
        | where Timestamp > ago(Window)
        | where FolderPath endswith "/.0/0.db" or FolderPath endswith "/.0/access-token" or FolderPath endswith "/.0/analytics-sent.log"
            or FolderPath endswith "/.0/analytics-id" or FolderPath has "/.0/runs/" or FolderPath startswith "/tmp/zero-engine/"
            or FolderPath endswith @"\.0\0.db" or FolderPath endswith @"\.0\access-token"
        | summarize Files=make_set(FolderPath, 10), Timestamp=min(Timestamp) by DeviceName
        | project Timestamp, DeviceName, Signal="0security state, access token or remote engine files", Detail=tostring(Files)),
    (DeviceNetworkEvents
        | where Timestamp > ago(Window)
        | where ActionType == "ListeningConnectionCreated" and LocalPort == 48123
        | where InitiatingProcessFileName in~ (ZeroImages) or InitiatingProcessCommandLine contains "0.js"
        | summarize Addresses=make_set(LocalIP, 5), Timestamp=min(Timestamp) by DeviceName, InitiatingProcessFileName
        | project Timestamp, DeviceName, Signal="0security console listening on 48123 (0.0.0.0 means server mode)",
            Detail=strcat(InitiatingProcessFileName, " ", tostring(Addresses)))
| order by Timestamp desc

// Indicator sweep with the agentic watchlist
// Agentic attack detections by ThreatDefence (0security). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1588.002 (Obtain Capabilities: Tool)
// Upload feeds/sentinel-watchlist.csv as a Microsoft Sentinel watchlist with the alias AGENTIC_IOCs and the search key
// "value". A match needs investigation. 0security publishes no attack infrastructure, so its rows are its user agents,
// its cloud host, its file and binary names, its Docker image, the probe and playbook canaries and the console strings.

let IOC = _GetWatchlist('AGENTIC_IOCs') | where framework has "zerosecurity" | project value=tostring(SearchKey), type, confidence, actor, source;
let IPList = toscalar(IOC | where type in ("ipv4", "ipv6") | summarize make_list(value));
let UAs = toscalar(IOC | where type == "user_agent" | summarize make_list(value));
let Domains = toscalar(IOC | where type == "domain" | summarize make_list(value));
let Names = toscalar(IOC | where type == "file_name" and confidence in ("high", "medium") | summarize make_list(value));
let Strings = toscalar(IOC | where type == "string" and confidence in ("high", "medium") | summarize make_list(value));
union isfuzzy=true
    (CommonSecurityLog | where TimeGenerated > ago(90d)
        | where SourceIP in (IPList) or DestinationIP in (IPList) or RequestClientApplication in (UAs) or DestinationHostName has_any (Domains)
            or RequestURL has_any (Strings)
        | project TimeGenerated, Source="CommonSecurityLog", Detail=RequestURL,
            Indicator=case(SourceIP in (IPList), SourceIP, DestinationIP in (IPList), DestinationIP, RequestClientApplication in (UAs), RequestClientApplication,
                DestinationHostName has_any (Domains), DestinationHostName, RequestURL)),
    (DeviceNetworkEvents | where Timestamp > ago(30d)
        | where RemoteIP in (IPList) or RemoteUrl has_any (Domains)
        | project TimeGenerated=Timestamp, Source="DeviceNetworkEvents", Indicator=iff(RemoteIP in (IPList), RemoteIP, RemoteUrl),
            Detail=strcat(DeviceName, " ", InitiatingProcessFileName)),
    (DeviceProcessEvents | where Timestamp > ago(30d)
        | where FileName in~ (Names)
        | project TimeGenerated=Timestamp, Source="DeviceProcessEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (DeviceFileEvents | where Timestamp > ago(30d)
        | where FileName in~ (Names)
        | project TimeGenerated=Timestamp, Source="DeviceFileEvents", Indicator=FileName, Detail=strcat(DeviceName, " ", FolderPath)),
    (DnsEvents | where TimeGenerated > ago(90d)
        | where Name has_any (Domains)
        | project TimeGenerated, Source="DnsEvents", Indicator=Name, Detail=ClientIP)
| join kind=leftouter (IOC) on $left.Indicator == $right.value
| summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), Details=make_set(Detail, 10)
    by Source, Indicator, actor, confidence
| order by LastSeen desc

// 0security client traffic, console calls and playbook canaries in proxy and web logs
// Agentic attack detections by ThreatDefence (0security). Source: https://github.com/ThreatDefence/agentic-attack-detections
// ATT&CK: T1595.002 (Active Scanning: Vulnerability Scanning), T1190 (Exploit Public-Facing Application), T1071.001 (Application Layer Protocol: Web Protocols)
// Example hunt for Microsoft Sentinel. Test and baseline before alerting.
// From the 0security source (0sec-labs/0security, reviewed at eec0d4c7):
//  - User agents it sets itself, visible to a decrypting proxy: 0security/<version> (PostHog analytics), @0/cli/update-check
//    (daily GitHub release check), @0/cli/<version> (cloud worker), 0security-audit-sink, 0security (Kimi sign-in), 0/1.0
//    (DuckDuckGo fallback search). Its cloud host is cloud.0.security.
//  - `0 probe` sends POST requests with no User-Agent at all (node:http), so a web log shows an empty user agent on POSTs
//    to a chat endpoint, from one source, 200 ms or more apart, two of each of ten prompts by default.
//  - Playbook canaries osec123xss and ZERO-INJ-OK in query strings, and the HTTP method ZERO.
//  - Console calls: /_access/login (server-mode sign-in) and /healthz on port 48123.

let UAs = dynamic(["0security", "0security-audit-sink", "0/1.0"]);
let Canaries = dynamic(["osec123xss", "ZERO-INJ-OK"]);
union isfuzzy=true
    (CommonSecurityLog
        | where TimeGenerated > ago(30d)
        | where RequestClientApplication startswith "0security/" or RequestClientApplication startswith "@0/cli/"
            or RequestClientApplication in (UAs) or DestinationHostName =~ "cloud.0.security"
            or RequestURL has_any (Canaries) or RequestURL endswith "/_access/login"
        | extend Signal = case(RequestURL has_any (Canaries), "playbook canary in a request",
            RequestURL endswith "/_access/login", "0security server-mode sign-in",
            DestinationHostName =~ "cloud.0.security", "0security cloud host", "0security client user agent")
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), URLs=make_set(RequestURL, 5),
            Agents=make_set(RequestClientApplication, 3) by Source="CommonSecurityLog", Src=SourceIP, Dst=DestinationHostName, Signal),
    (W3CIISLog
        | where TimeGenerated > ago(30d)
        | where csUriQuery has_any (Canaries) or csMethod == "ZERO"
            or (csMethod =~ "POST" and (isempty(csUserAgent) or csUserAgent == "-") and csUriStem has_any ("chat", "completions", "messages", "ask", "agent"))
        | extend Signal = case(csUriQuery has_any (Canaries), "playbook canary in a query", csMethod == "ZERO", "bogus method ZERO",
            "POST to a chat endpoint with no user agent (0 probe sends none)")
        | summarize Events=count(), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated), URLs=make_set(strcat(csUriStem, "?", csUriQuery), 5),
            Agents=make_set(csUserAgent, 3) by Source="W3CIISLog", Src=cIP, Dst=sSiteName, Signal)
| order by Events desc
